# ---------- 烛心站点：播报快照（只保留最新一次） ----------
# 容器内路径（映射到宿主机 /data/astrbot/data/）
_BC_SNAPSHOT = "/AstrBot/data/latest_broadcast.json"
_BC_SNAPSHOT_ALT = "/data/astrbot/data/latest_broadcast.json"


def _zhuxin_save_broadcast_img(kind, data=None, src_path=None):
    # 保存播报图（覆盖式，只留最新一次）
    # data: raw bytes；src_path: 本地图片路径
    paths = ["/AstrBot/data/latest_broadcast_%s.png" % kind,
             "/data/astrbot/data/latest_broadcast_%s.png" % kind]
    try:
        if data:
            for p in paths:
                try:
                    with open(p, "wb") as f:
                        f.write(data)
                    return True
                except Exception:
                    continue
        elif src_path:
            import shutil as _sh
            for p in paths:
                try:
                    _sh.copyfile(src_path, p)
                    return True
                except Exception:
                    continue
    except Exception:
        pass
    return False


def _zhuxin_save_broadcast(kind, groups):
    """把本次播报写进快照文件（覆盖式，只留最新一次）。"""
    try:
        import json as _json
        import time as _time
        total = 0
        items = []
        for gid, info in (groups or {}).items():
            lines = [str(x) for x in (info.get("lines") or []) if str(x).strip()]
            if not lines:
                continue
            total += len(lines)
            items.append({
                "g": "" if gid == "__broadcast__" else str(gid),
                "n": len(lines),
                "lines": lines[:200],
            })
        if total == 0:
            return
        rec = {
            "t": int(_time.time()),
            "time": _time.strftime("%Y-%m-%d %H:%M:%S"),
            "kind": kind,
            "total": total,
            "groups": items,
        }
        payload = _json.dumps(rec, ensure_ascii=False)
        for path in (_BC_SNAPSHOT, _BC_SNAPSHOT_ALT):
            try:
                with open(path, "w", encoding="utf-8") as f:
                    f.write(payload)
                break
            except Exception:
                continue
    except Exception:
        pass


class _BizError(Exception):
    """业务错误：抛出后事务回滚并返回友好提示"""

    def __init__(self, msg: str):
        super().__init__(msg)
        self.msg = msg


# ============================================================
#  浏览器限定游玩模式（browser_only_mode）
#  开关打开后，插件在聊天平台的所有指令一律失效，
#  统一引导玩家前往网页端完成玩法。
# ============================================================
BROWSER_ONLY_SITE = "https://烛心.xyz"
# 默认引导文案；可在配置页用 browser_only_text 覆盖（留空则用此默认值）
BROWSER_ONLY_TIP = (
    "🌐 本群积分游戏已切换为「仅限浏览器游玩」模式喵~\n"
    "请到浏览器上完成相应的玩法：\n"
    f"{BROWSER_ONLY_SITE}"
)


class _BrowserOnlyFilter(CustomFilter):
    """浏览器限定模式的统一拦截器（开关关闭时一律放行）。"""

    def __init__(self, plugin, raise_error: bool = True, **kwargs) -> None:
        super().__init__(raise_error, **kwargs)
        self._plugin = plugin

    def _flag(self) -> bool:
        try:
            flags = getattr(self._plugin, "feature_flags", None) or {}
            return bool(flags.get("browser_only_mode", False))
        except Exception:
            return False

    def filter(self, event: AstrMessageEvent, cfg) -> bool:
        if not self._flag():
            return True      # 未开启，放行
        return False         # 已开启，拦截（由提示 handler 统一回复）

    def __call__(self, event):
        return self.filter(event, None)


class _ExactPointsCommandFilter(CustomFilter):
    """只匹配单独的 /积分，避免抢占 /子指令。"""

    def filter(self, event: AstrMessageEvent, cfg) -> bool:
        try:
            return event.get_message_str().strip() == "积分"
        except Exception:
            return False


