    # ============================================================
    @filter.command("买彩票", alias={"彩票"})
    async def lottery_buy(self, event: AstrMessageEvent):
        """/买彩票 [积分数量] —— 购买1注随机号码，每人每期限购10注"""
        ok_gate, msg_gate = await self._check_group_gate(event, "买彩票")
        if not ok_gate:
            yield event.plain_result(msg_gate)
            return
        user_id = event.get_sender_id()
        cost = self.LOTTERY_DEFAULT_COST
        args = self._strip_command(event, "买彩票")
        if not args:
            args = self._strip_command(event, "彩票")
        if args:
            try:
                cost = int(args.split()[0])
                if cost <= 0:
                    raise ValueError
            except ValueError:
                yield event.plain_result("积分数量得是正整数喵~")
                return
        today = date.today().isoformat()
        platform_id = event.get_platform_id()
        group_id = event.get_group_id()

        async def fn(session):
            remaining = await self._enforce_cooldown(session, user_id)
            if remaining > 0:
                raise _BizError(f"操作太频繁啦，请 {remaining} 秒后再试喵~")
            cnt = (
                await session.execute(
                    text("SELECT COUNT(*) FROM lottery WHERE user_id=:u AND period=:p"),
                    {"u": user_id, "p": today},
                )
            ).first()
            if int(cnt[0]) >= self.LOTTERY_LIMIT_PER_DAY:
                raise _BizError(f"每人每期限购 {self.LOTTERY_LIMIT_PER_DAY} 注喵~")
            bal = await self._total_balance(session, user_id)
            if bal < cost:
                raise _BizError(f"积分不足喵~ 需要 {cost} 积分，你只有 {bal} 积分")
            numbers = sorted(random.sample(range(1, 101), 5))
            await self._add_points(session, user_id, -cost, "购买彩票")
            # 检查消费达标提醒
            should_remind = await self._check_spend_reward(session, user_id, event.get_group_id())
            await session.execute(
                text(
                    "INSERT INTO lottery(user_id, numbers, cost, period, platform_id, group_id) "
                    "VALUES(:u, :n, :c, :p, :pid, :gid)"
                ),
                {"u": user_id, "n": json.dumps(numbers), "c": cost,
                 "p": today, "pid": platform_id, "gid": group_id},
            )
            return True, (
                f"🎰 购彩成功！你的号码：{' '.join(map(str, numbers))}\n"
                f"花费 {cost} 积分，今日已购 {int(cnt[0]) + 1}/{self.LOTTERY_LIMIT_PER_DAY} 注\n"
                f"⏰ 每日 20:00 开奖，祝好运喵~"
            ), should_remind

        ok, msg, should_remind = await self._tx(fn)
        yield event.plain_result(msg)
        # 事务外发送提醒
        if ok and should_remind:
            group_id = event.get_group_id()
            if group_id:
                try:
                    yield event.plain_result(
                    )
                except Exception:
                    pass

    @filter.command("彩票奖池")
    async def lottery_pool_status(self, event: AstrMessageEvent):
        """/彩票奖池"""
        ok_gate, msg_gate = await self._check_group_gate(event, "彩票奖池")
        if not ok_gate:
            yield event.plain_result(msg_gate)
            return
        today = date.today().isoformat()

        async def fn(session):
            bought = (
                await session.execute(
                    text("SELECT COALESCE(SUM(cost),0), COUNT(DISTINCT user_id) FROM lottery WHERE period=:p"),
                    {"p": today},
                )
            ).first()
            carry = 0
            prev = (date.today() - timedelta(days=1)).isoformat()
            c_row = (
                await session.execute(
                    text("SELECT pool FROM lottery_pool WHERE period=:p"), {"p": prev}
                )
            ).first()
            if c_row:
                carry = int(c_row[0])
            pool = int(bought[0]) + self.LOTTERY_BASE_POOL + carry
            return True, (
                f"🎰 大乐透奖池（{today}）\n"
                f"当前奖池：{pool} 积分（购买 {int(bought[0])} + 保底 {self.LOTTERY_BASE_POOL} + 上期结转 {carry}）\n"
                f"参与人数：{int(bought[1])}\n"
                f"⏰ 每日 20:00 开奖，发送 /买彩票 参与喵~"
            ), None

        ok, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    # ============================================================
    #  功能五：谁是卧底（群聊）
    # ============================================================
    @filter.command("卧底开始")
    async def uc_start(self, event: AstrMessageEvent):
        """/卧底开始 [人数] —— 发起卧底游戏报名"""
        if event.is_private_chat():
            yield event.plain_result("卧底游戏需要在群里玩喵~")
            return
        ok_gate, msg_gate = await self._check_group_gate(event, "卧底开始")
        if not ok_gate:
            yield event.plain_result(msg_gate)
            return
        group_id = event.get_group_id()
        invoker = event.get_sender_id()
        platform_id = event.get_platform_id()
        target = self.UC_DEFAULT_PLAYERS
        args = self._strip_command(event, "卧底开始")
        if args:
            try:
                target = int(args.split()[0])
                if target < self.UC_MIN_PLAYERS or target > self.UC_MAX_PLAYERS:
                    raise ValueError
            except ValueError:
                yield event.plain_result(f"人数需要是 {self.UC_MIN_PLAYERS}-{self.UC_MAX_PLAYERS} 的整数喵~")
                return

        async def fn(session):
            remaining = await self._enforce_cooldown(session, invoker)
            if remaining > 0:
                raise _BizError(f"操作太频繁啦，请 {remaining} 秒后再试喵~")
            exist = (
                await session.execute(
                    text("SELECT id FROM undercover_games WHERE group_id=:g AND status IN ('waiting','speech','voting')"),
                    {"g": group_id},
                )
            ).first()
            if exist:
                raise _BizError("本群已有进行中的卧底游戏喵~")
            votes = json.dumps({"target": target, "eliminated": [], "votes": {}}, ensure_ascii=False)
            await session.execute(
                text(
                    "INSERT INTO undercover_games(group_id, status, players, civilian_word, undercover_word, "
                    "undercover_id, votes, round, current_speaker_index, phase, platform_id, updated_at) "
                    "VALUES(:g, 'waiting', :p, '', '', '', :v, 1, 0, 'lobby', :pid, :t)"
                ),
                {"g": group_id, "p": json.dumps([invoker]), "v": votes,
                 "pid": platform_id, "t": time.time()},
            )
            # 报名超时自动取消
            job = self._scheduler.add_job(
                self._uc_lobby_timeout, "date",
                run_date=datetime.now(TZ) + timedelta(seconds=self.UC_LOBBY_SECONDS),
                id=f"uc_lobby_{group_id}", replace_existing=True,
                args=[group_id],
            )
            self._uc_jobs[f"lobby_{group_id}"] = job
            return True, (
                f"🕵️ 卧底游戏报名开始！目标 {target} 人（当前 1/{target}）\n"
                f"发送 /加入卧底 报名喵~ 报名满自动开局，{self.UC_LOBBY_SECONDS} 秒内未满则取消"
            ), None

        ok, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    @filter.command("加入卧底")
    async def uc_join(self, event: AstrMessageEvent):
        """/加入卧底 —— 报名卧底游戏"""
        if event.is_private_chat():
            yield event.plain_result("卧底游戏需要在群里玩喵~")
            return
        ok_gate, msg_gate = await self._check_group_gate(event, "加入卧底")
        if not ok_gate:
            yield event.plain_result(msg_gate)
            return
        group_id = event.get_group_id()
        user_id = event.get_sender_id()

        async def fn(session):
            remaining = await self._enforce_cooldown(session, user_id)
            if remaining > 0:
                raise _BizError(f"操作太频繁啦，请 {remaining} 秒后再试喵~")
            row = (
                await session.execute(
                    text("SELECT players, votes FROM undercover_games WHERE group_id=:g AND status='waiting'"),
                    {"g": group_id},
                )
            ).first()
            if not row:
                raise _BizError("本群没有等待中的卧底游戏喵~ 发送 /卧底开始 发起")
            players = json.loads(row[0])
            votes_data = json.loads(row[1])
            target = int(votes_data.get("target", self.UC_DEFAULT_PLAYERS))
            if user_id in players:
                raise _BizError("你已经报名啦喵~")
            if len(players) >= target:
                raise _BizError("报名已满，等待开局喵~")
            players.append(user_id)
            if len(players) >= target:
                # 满员自动开局
                await self._uc_launch(session, group_id, players, votes_data)
                job = self._uc_jobs.pop(f"lobby_{group_id}", None)
                if job:
                    try:
                        job.remove()
                    except Exception:
                        pass
                return True, "🕵️ 报名满员，卧底游戏开始！", None
            await session.execute(
                text("UPDATE undercover_games SET players=:p, updated_at=:t WHERE group_id=:g"),
                {"p": json.dumps(players), "t": time.time(), "g": group_id},
            )
            return True, f"✅ 报名成功！当前 {len(players)}/{target} 人喵~", None

        ok, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    async def _uc_launch(self, session, group_id: str, players: list, votes_data: dict):
        """满员后正式开局：发词、宣布第一位发言人。必须在事务内调用"""
        pair = random.choice(WORD_PAIRS)
        undercover_id = random.choice(players)
        civilian_word, undercover_word = pair
        now = time.time()
        await session.execute(
            text(
                "UPDATE undercover_games SET status='speech', phase='speech', players=:p, "
                "civilian_word=:cw, undercover_word=:uw, undercover_id=:ui, "
                "votes=:v, round=1, current_speaker_index=0, updated_at=:t WHERE group_id=:g"
            ),
            {"p": json.dumps(players), "cw": civilian_word, "uw": undercover_word,
             "ui": undercover_id, "v": json.dumps(votes_data, ensure_ascii=False),
             "t": now, "g": group_id},
        )
        # 私聊发词（尽力而为，失败则公开提示）
        pid_row = (
            await session.execute(
                text("SELECT platform_id FROM undercover_games WHERE group_id=:g"), {"g": group_id}
            )
        ).first()
        platform_id = pid_row[0] if pid_row else ""
        for uid in players:
            word = undercover_word if uid == undercover_id else civilian_word
            ok_sent = await self._send_private(platform_id, uid, f"🕵️ 你的卧底词语是：【{word}】喵~ 别让卧底发现你！")
            if not ok_sent:
                await self._send_group_chain(platform_id, group_id, [
                    At(qq=str(uid)),
                    Plain(f" 私聊发词失败，你的词是：【{word}】（注意保密喵~）"),
                ])
        await self._uc_schedule_next(session, group_id)

    def _alive_players(self, players: list, eliminated: list) -> list:
        return [p for p in players if p not in eliminated]

    async def _uc_schedule_next(self, session, group_id: str):
        """安排下一个发言人（或进入投票）。必须在事务内调用，且调用前需读取最新游戏数据"""
        row = (
            await session.execute(
                text("SELECT players, votes, current_speaker_index, phase, status, round, platform_id FROM undercover_games WHERE group_id=:g"),
                {"g": group_id},
            )
        ).first()
        if not row or row[4] not in ("speech", "voting"):
            return
        players = json.loads(row[0])
        votes_data = json.loads(row[1])
        eliminated = votes_data.get("eliminated", [])
        alive = self._alive_players(players, eliminated)
        idx = int(row[2])
        phase = row[3]
        current_round = int(row[5])
        platform_id = row[6] or ""
        if phase == "speech":
            if idx >= len(alive):
                # 本轮发言结束 → 进入投票
                await session.execute(
                    text("UPDATE undercover_games SET phase='voting', updated_at=:t WHERE group_id=:g"),
                    {"t": time.time(), "g": group_id},
                )
                await self._send_to_group(platform_id, group_id,
                    "🗳️ 发言结束，进入投票阶段！发送 /投票 @某人 投出你怀疑的卧底"
                    f"（限时 {self.UC_VOTE_SECONDS} 秒）")
                # 投票超时自动计票
                job = self._scheduler.add_job(
                    self._uc_vote_timer, "date",
                    run_date=datetime.now(TZ) + timedelta(seconds=self.UC_VOTE_SECONDS),
                    id=f"uc_vote_{group_id}", replace_existing=True, args=[group_id],
                )
                self._uc_jobs[f"vote_{group_id}"] = job
            else:
                speaker = alive[idx]
                await session.execute(
                    text("UPDATE undercover_games SET current_speaker_index=:i, updated_at=:t WHERE group_id=:g"),
                    {"i": idx + 1, "t": time.time(), "g": group_id},
                )
                try:
                    await self._send_to_session(
                        platform_id, _MessageType.GROUP_MESSAGE, group_id,
                        MessageChain([
                            Plain(f"🎤 第 {current_round} 轮发言，轮到："),
                            At(qq=str(speaker)),
                            Plain(f"（限时 {self.UC_SPEECH_SECONDS} 秒）"),
                        ]),
                    )
                except Exception:
                    pass
                job = self._scheduler.add_job(
                    self._uc_speech_timer, "date",
                    run_date=datetime.now(TZ) + timedelta(seconds=self.UC_SPEECH_SECONDS),
                    id=f"uc_speech_{group_id}", replace_existing=True, args=[group_id],
                )
                self._uc_jobs[f"speech_{group_id}"] = job

    async def _uc_speech_timer(self, group_id: str):
        """发言倒计时结束：轮到下一位或进入投票"""
        async def fn(session):
            row = (
                await session.execute(
                    text("SELECT status, phase FROM undercover_games WHERE group_id=:g"), {"g": group_id}
                )
            ).first()
            if not row or row[0] != "speech":
                return True, "跳过", None
            await self._uc_schedule_next(session, group_id)
            return True, "下一位", None

        await self._tx(fn)

    async def _uc_vote_timer(self, group_id: str):
        """投票倒计时结束：在事务中自动计票"""
        async def fn(session):
            await self._uc_process_votes(session, group_id)
            return True, "投票计时结束", None

        await self._tx(fn)
        self._uc_jobs.pop(f"vote_{group_id}", None)

    async def _uc_lobby_timeout(self, group_id: str):
        """报名超时自动取消"""
        async def fn(session):
            row = (
                await session.execute(
                    text("SELECT status, players, platform_id FROM undercover_games WHERE group_id=:g"),
                    {"g": group_id},
                )
            ).first()
            if not row or row[0] != "waiting":
                return True, "跳过", None
            players = json.loads(row[1])
            platform_id = row[2] or ""
            await session.execute(
                text("DELETE FROM undercover_games WHERE group_id=:g"), {"g": group_id}
            )
            await self._send_to_group(platform_id, group_id,
                f"🕵️ 卧底报名超时取消喵~（仅 {len(players)} 人报名）")
            return True, "已取消", None

        ok, msg, _ = await self._tx(fn)
        self._uc_jobs.pop(f"lobby_{group_id}", None)

    @filter.command("投票")
    async def uc_vote(self, event: AstrMessageEvent):
        """/投票 @某人 —— 投票阶段投出卧底"""
        if event.is_private_chat():
            yield event.plain_result("卧底游戏需要在群里玩喵~")
            return
        if not self.feature_flags.get("enable_undercover", True):
            yield event.plain_result("谁是卧底玩法已在配置页关闭喵~")
            return
        ok_gate, msg_gate = await self._check_group_gate(event, "投票")
        if not ok_gate:
            yield event.plain_result(msg_gate)
            return
        group_id = event.get_group_id()
        voter = event.get_sender_id()
        target = self._extract_at(event)
        if not target:
            yield event.plain_result("用法：/投票 @某人 喵~")
            return

        async def fn(session):
            remaining = await self._enforce_cooldown(session, voter)
            if remaining > 0:
                raise _BizError(f"操作太频繁啦，请 {remaining} 秒后再试喵~")
            row = (
                await session.execute(
                    text("SELECT status, phase, players, votes FROM undercover_games WHERE group_id=:g"),
                    {"g": group_id},
                )
            ).first()
            if not row or row[0] not in ("speech", "voting"):
                raise _BizError("本群没有进行中的卧底游戏喵~")
            if row[1] != "voting":
                raise _BizError("现在不是投票阶段喵~ 等发言结束后再投")
            players = json.loads(row[2])
            votes_data = json.loads(row[3])
            eliminated = votes_data.get("eliminated", [])
            alive = self._alive_players(players, eliminated)
            if voter not in alive:
                raise _BizError("你已出局，不能投票喵~")
            if target not in alive:
                raise _BizError("投票对象不合法喵~（只能投还在场的玩家）")
            if target == voter:
                raise _BizError("不能投自己喵~")
            votes_data.setdefault("votes", {})[voter] = target
            await session.execute(
                text("UPDATE undercover_games SET votes=:v, updated_at=:t WHERE group_id=:g"),
                {"v": json.dumps(votes_data, ensure_ascii=False), "t": time.time(), "g": group_id},
            )
            voted = len(votes_data["votes"])
            if voted >= len(alive):
                await self._uc_process_votes(session, group_id)
                return True, "投票完毕，正在计票喵~", None
            return True, f"✅ 已投票（{voted}/{len(alive)}）喵~", None

        ok, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    async def _uc_process_votes(self, session, group_id: str):
        """统计票数、淘汰最高票者、判定胜负、进入下一轮。必须在事务内调用"""
        row = (
            await session.execute(
                text("SELECT players, votes, undercover_id, round, phase, status, platform_id, civilian_word, undercover_word FROM undercover_games WHERE group_id=:g"),
                {"g": group_id},
            )
        ).first()
        if not row or row[5] != "voting":
            return
        players = json.loads(row[0])
        votes_data = json.loads(row[1])
        undercover_id = row[2]
        current_round = int(row[3])
        platform_id = row[6] or ""
        civilian_word = row[7] or ""
        undercover_word = row[8] or ""
        eliminated = votes_data.get("eliminated", [])
        alive = self._alive_players(players, eliminated)
        votes = votes_data.get("votes", {})
        # 计票
        tally: dict[str, int] = {}
        for v in votes.values():
            tally[v] = tally.get(v, 0) + 1
        max_votes = max(tally.values()) if tally else 0
        top = [k for k, v in tally.items() if v == max_votes] if max_votes > 0 else []
        if len(top) == 1:
            out = top[0]
            eliminated.append(out)
            votes_data["eliminated"] = eliminated
            votes_data["votes"] = {}
            if out == undercover_id:
                # 卧底被投出：平民获胜
                await session.execute(
                    text("DELETE FROM undercover_games WHERE group_id=:g"), {"g": group_id}
                )
                await self._send_to_group(platform_id, group_id,
                    f"🔍 卧底【{out}】被投出局！平民获胜！🎉\n"
                    f"卧底词：【{undercover_word}】 平民词：【{civilian_word}】")
                self._cancel_uc_jobs(group_id)
                return
            alive_after = self._alive_players(players, eliminated)
            if len(alive_after) <= 2:
                # 卧底活到最后：卧底获胜
                await session.execute(
                    text("DELETE FROM undercover_games WHERE group_id=:g"), {"g": group_id}
                )
                await self._send_to_group(platform_id, group_id,
                    f"🕵️ 场上只剩 {len(alive_after)} 人，卧底【{undercover_id}】存活到最后，卧底获胜！🎭\n"
                    f"卧底词：【{undercover_word}】 平民词：【{civilian_word}】")
                self._cancel_uc_jobs(group_id)
                return
            # 平民出局，进入下一轮发言
            await session.execute(
                text(
                    "UPDATE undercover_games SET votes=:v, round=round+1, current_speaker_index=0, "
                    "phase='speech', status='speech', updated_at=:t WHERE group_id=:g"
                ),
                {"v": json.dumps(votes_data, ensure_ascii=False), "t": time.time(), "g": group_id},
            )
            await self._send_to_group(platform_id, group_id,
                f"🚪 玩家【{out}】被投出局！场上还剩 {len(alive_after)} 人，进入第 {current_round + 1} 轮发言！")
            await self._uc_schedule_next(session, group_id)
        else:
            # 平票：无人出局
            votes_data["votes"] = {}
            await session.execute(
                text(
                    "UPDATE undercover_games SET votes=:v, round=round+1, current_speaker_index=0, "
                    "phase='speech', status='speech', updated_at=:t WHERE group_id=:g"
                ),
                {"v": json.dumps(votes_data, ensure_ascii=False), "t": time.time(), "g": group_id},
            )
            await self._send_to_group(platform_id, group_id,
                f"🤝 平票！本轮无人出局，进入第 {current_round + 1} 轮发言喵~")
            await self._uc_schedule_next(session, group_id)

    def _cancel_uc_jobs(self, group_id: str):
        for key in (f"speech_{group_id}", f"vote_{group_id}", f"lobby_{group_id}"):
            job = self._uc_jobs.pop(key, None)
            if job:
                try:
                    job.remove()
                except Exception:
                    pass

    @filter.command("卧底结束")
    @filter.permission_type(PermissionType.ADMIN)
    async def uc_end(self, event: AstrMessageEvent):
        """/卧底结束 —— 管理员强制结束"""
        if event.is_private_chat():
            yield event.plain_result("卧底游戏需要在群里玩喵~")
            return
        group_id = event.get_group_id()

        async def fn(session):
            row = (
                await session.execute(
                    text("SELECT id FROM undercover_games WHERE group_id=:g AND status IN ('waiting','speech','voting')"),
                    {"g": group_id},
                )
            ).first()
            if not row:
                raise _BizError("本群没有进行中的卧底游戏喵~")
            await session.execute(
                text("DELETE FROM undercover_games WHERE group_id=:g"), {"g": group_id}
            )
            self._cancel_uc_jobs(group_id)
            return True, "🕵️ 卧底游戏已强制结束喵~", None

        ok, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    async def _get_group_member(self, event: AstrMessageEvent, user_id: str):
        """查询目标是否仍在当前群，返回成员信息或 None。"""
        try:
            group = await event.get_group(event.get_group_id())
            if group and group.members:
                target = str(user_id)
                for member in group.members:
                    if str(member.user_id) == target:
                        return member
        except Exception as exc:
            self.logger.warning(f"查询群成员失败: {exc}")
        return None

    def _extract_at(self, event: AstrMessageEvent) -> Optional[str]:
        """从消息中提取被 @ 的 QQ（兼容 At 组件与纯文本数字）"""
        try:
            for comp in event.get_messages():
                if isinstance(comp, At):
                    return str(comp.qq)
        except Exception:
            pass
        m = re.search(r"(\d{5,})", event.get_message_str())
        return m.group(1) if m else None

    def _strip_command(self, event: AstrMessageEvent, command: str) -> str:
        """从事件消息中提取指令参数。

        兼容不同 AstrBot 版本的 message_str 差异：命令词可能带/不带斜杠、
        消息可能带 @机器人 尾巴、可能含全角空格，统一清理后返回参数部分。
        """
        text = ""
        try:
            text = str(event.message_str or "")
        except Exception:
            text = ""
        if not text:
            try:
                text = str(event.get_message_str() or "")
            except Exception:
                text = ""
        if not text:
            try:
                parts = []
                for comp in event.get_messages():
                    t = getattr(comp, "get_text", None)
                    parts.append(t() if t else str(comp))
                text = " ".join(parts)
            except Exception:
                pass
        cmd = command.lstrip("/")
        variants = [command, cmd, "/" + cmd]
        # 兼容只保留子指令文本的事件对象；实际注册仍只接受 /前缀。
        if " " in cmd:
            child = cmd.split(" ", 1)[1]
            variants.extend([child, "/" + child])
        for variant in variants:
            if variant and variant in text:
                text = text.split(variant, 1)[1]
                break
        # 全角空格转半角，去掉首尾与连续空白
        return " ".join(text.replace("　", " ").split())

    # ============================================================
    #  功能六：掷骰比大小
    # ============================================================
    async def _dice_count(self, session, user_id: str, today: str) -> int:
        row = (await session.execute(text(
            "SELECT count FROM dice_records WHERE user_id=:u AND date=:d"
        ), {"u": user_id, "d": today})).first()
        return int(row[0]) if row else 0

    async def _increase_dice_count(self, session, user_id: str, today: str) -> None:
        await session.execute(text(
            "INSERT INTO dice_records(user_id, date, count) VALUES(:u, :d, 1) "
            "ON CONFLICT(user_id, date) DO UPDATE SET count=dice_records.count+1"
        ), {"u": user_id, "d": today})

    @filter.command("掷骰")
    async def dice_roll(self, event: AstrMessageEvent):
        """/掷骰 @群友 —— 与群友比大小，每日次数可在配置页调整。"""
        if event.is_private_chat():
            yield event.plain_result("掷骰只能在群里玩喵~")
            return
        ok_gate, msg_gate = await self._check_group_gate(event, "掷骰")
        if not ok_gate:
            yield event.plain_result(msg_gate)
            return
        challenger = str(event.get_sender_id()).strip()
        target = self._extract_at(event)
        if not target:
            yield event.plain_result("用法：/掷骰 @群友 喵~")
            return
        if target == challenger:
            yield event.plain_result("不能和自己掷骰喵~")
            return
        # 兼容 NapCat/OneBot：无需强依赖群成员查询接口，@ 到 QQ 即可参与。
        # 能取到群昵称则展示昵称，取不到也不阻断玩法。
        member = await self._get_group_member(event, target)
        target_name = str(getattr(member, "nickname", "") or "群友").strip()
        challenger_name = str(event.get_sender_name() or "你").strip()
        today = date.today().isoformat()

        async with self._dice_lock:
            async def fn(session):
                challenger_count = await self._dice_count(session, challenger, today)
                target_count = await self._dice_count(session, target, today)
                if challenger_count >= self.DICE_DAILY_LIMIT:
                    raise _BizError(f"你今天已经掷骰 {self.DICE_DAILY_LIMIT} 次啦喵~")
                if target_count >= self.DICE_DAILY_LIMIT:
                    raise _BizError(f"{target_name} 今天已经达到掷骰次数上限喵~")
                await self._ensure_user(session, challenger, challenger_name)
                await self._ensure_user(session, target, target_name)
                first = random.randint(1, 6)
                second = random.randint(1, 6)
                await self._increase_dice_count(session, challenger, today)
                await self._increase_dice_count(session, target, today)
                chain = [Plain(f"🎲 你掷出了 {first}，"), At(qq=str(target)), Plain(f" {target_name} 掷出了 {second}\n")]
                if first > second:
                    await self._add_points(session, challenger, 10, "掷骰获胜")
                    chain.append(Plain("🎉 你赢了！获得10积分！"))
                elif first < second:
                    await self._add_points(session, target, 10, "掷骰获胜")
                    chain.extend([At(qq=str(target)), Plain(f" 赢了！获得10积分！")])
                else:
                    await self._add_points(session, challenger, 5, "掷骰平局")
                    await self._add_points(session, target, 5, "掷骰平局")
                    chain.append(Plain("🤝 平局！各得5积分！"))
                return True, "ok", chain

            ok, msg, data = await self._tx(fn)
        if ok and data:
            # AstrBot 官方 chain_result 接收组件列表，不能再套一层 MessageChain。
            yield event.chain_result(data)
        else:
            yield event.plain_result(msg)

    # ============================================================
    #  功能：积分转账
    # ============================================================
    def _parse_transfer_args(self, event: AstrMessageEvent, args: list[str]):
        """解析转账参数，返回 (目标QQ, 金额, 是否显式@了人)。

        兼容两种目标写法：群聊 @张三（At 组件）和纯 QQ 号（私聊/群聊均可）。
        金额取参数中最后一个纯数字；目标取 At 组件优先，其次第一个 5 位以上数字。
        """
        at_qq = self._extract_at(event)
        nums = [a for a in args if a.isdigit()]
        amount = int(nums[-1]) if nums else None
        target = at_qq
        if not target and len(nums) >= 2:
            # 没有 At 组件时，第一个数字视为目标 QQ（金额取最后一个）
            target = nums[0]
        explicit_at = bool(at_qq)
        return target, amount, explicit_at

    @filter.command("转账")
    async def transfer_points(self, event: AstrMessageEvent):
        """/转账 @群友 或 QQ号 [积分] —— 转账积分给其他玩家，收取10%手续费。"""
        is_private = event.is_private_chat()
        args = self._strip_command(event, "转账").split()
        target, amount, explicit_at = self._parse_transfer_args(event, args)

        # 目标校验：群聊必须 @，私聊必须给 QQ 号
        if not target:
            if is_private:
                yield event.plain_result("❌ 请提供目标用户QQ号，如：/转账 123456 50")
            else:
                yield event.plain_result("❌ 请@要转账的群友，如：/转账 @张三 50")
            return
        sender = str(event.get_sender_id()).strip()
        if target == sender:
            yield event.plain_result("❌ 不能转账给自己！")
            return
        # 金额校验：1-5000 积分
        if amount is None or not (self.TRANSFER_MIN <= amount <= self.TRANSFER_MAX):
            yield event.plain_result("❌ 请输入有效的转账金额（1-5000积分）")
            return

        # 群聊时顺带查一下目标昵称（查不到也不阻断，兜底用 QQ 号）
        target_name = ""
        if not is_private:
            member = await self._get_group_member(event, target)
            if member:
                target_name = str(getattr(member, "nickname", "") or "").strip()

        fee = int(amount * self.TRANSFER_FEE_RATE)  # 手续费：10% 向下取整
        total = amount + fee

        async def fn(session):
            # 冷却检查：查本表最近一次转账时间（独立于全局指令冷却，互不影响）
            row = (await session.execute(text(
                "SELECT MAX(create_time) FROM transfer_records WHERE from_user=:u"
            ), {"u": sender})).first()
            if row and row[0] is not None:
                wait = self.TRANSFER_COOLDOWN - (time.time() - float(row[0]))
                if wait > 0:
                    raise _BizError(f"⏳ 操作太快，请等待 {int(wait) + 1} 秒后再试")
            # 每日次数检查：按北京时间当天 0 点起统计
            midnight = datetime.now(TZ).replace(
                hour=0, minute=0, second=0, microsecond=0
            ).timestamp()
            row = (await session.execute(text(
                "SELECT COUNT(*) FROM transfer_records "
                "WHERE from_user=:u AND create_time>=:t"
            ), {"u": sender, "t": midnight})).first()
            used = int(row[0]) if row else 0
            if used >= self.TRANSFER_DAILY_LIMIT:
                raise _BizError("❌ 今日转账次数已达上限（10次）")
            # 目标用户校验：私聊要求对方已在积分系统注册；群聊里对方是本群成员则自动建档
            # 注意：db_name 是 fn 内局部变量；直接对外层 target_name 赋值会让它变成
            # 局部变量（闭包陷阱），读取时触发 UnboundLocalError
            db_name = ""
            row = (await session.execute(text(
                "SELECT user_name FROM users WHERE user_id=:u"
            ), {"u": target})).first()
            if not row:
                if is_private:
                    raise _BizError("❌ 目标用户不存在")
                if not target_name:
                    raise _BizError("❌ 目标用户不存在")
                await self._ensure_user(session, target, target_name)
            else:
                db_name = str(row[0] or "").strip()
            # 余额校验：转账只能用普通余额（贷款余额不可转账，防止套现）
            row = (await session.execute(text(
                "SELECT balance, loan_balance FROM users WHERE user_id=:u"
            ), {"u": sender})).first()
            normal_balance = int(row[0]) if row else 0
            loan_bal = int(row[1]) if row else 0
            if normal_balance < total:
                if loan_bal > 0:
                    raise _BizError(
                        f"❌ 普通余额不足！当前普通余额：{normal_balance}积分\n"
                        f"贷款余额：{loan_bal}积分（不可转账）\n"
                        "请先还清贷款或赚取普通积分后再转账")
                raise _BizError(
                    f"❌ 积分不足！本次转账需扣除 {total} 积分"
                    f"（转账{amount}+手续费{fee}），当前余额：{normal_balance}积分")
            # 转出方扣除 转账金额+手续费（force_normal 只扣普通余额）
            await self._add_points(session, sender, -total, "transfer_out",
                                   earned=0, spent=total, force_normal=True)
            # 接收方到账 转账金额
            await self._add_points(session, target, amount, "transfer_in",
                                   earned=amount, spent=0)
            # 手续费流入系统钱包（资金池），不再进管理员个人账户
            if fee > 0:
                await self._wallet_inflow_s(
                    session, fee, "transfer_fee", f"{sender} → {target} 转账手续费"
                )
                fee_note = f"💸 手续费：{fee}积分（已存入系统钱包）\n"
            else:
                fee_note = ""
            # 写转账记录（用北京时间时间戳，便于冷却/每日次数统计）
            await session.execute(text(
                "INSERT INTO transfer_records(from_user, to_user, amount, fee, total, create_time) "
                "VALUES(:f, :t, :a, :fee, :tot, :time)"
            ), {"f": sender, "t": target, "a": amount, "fee": fee,
                "tot": total, "time": time.time()})
            new_balance = await self._balance(session, sender)
            remaining = self.TRANSFER_DAILY_LIMIT - used - 1
            should_remind = await self._check_spend_reward(session, sender,
                                                           event.get_group_id())
            display_name = target_name or db_name or target
            if is_private:
                msg = (f"✅ 转账成功！用户 {display_name} 收到 {amount}积分\n"
                       f"{fee_note}"
                       f"你实际扣除：{total}积分\n"
                       f"当前余额：{new_balance}积分\n"
                       f"今日剩余转账次数：{remaining}次")
                chain = None
            else:
                # 群聊用真实 CQ 码（At 组件）@目标用户
                msg = (f"✅ 转账成功！@{display_name} 收到 {amount}积分\n"
                       f"{fee_note}"
                       f"你实际扣除：{total}积分\n"
                       f"当前余额：{new_balance}积分\n"
                       f"今日剩余转账次数：{remaining}次")
                chain = [Plain("✅ 转账成功！"), At(qq=str(target)),
                         Plain(f" 收到 {amount}积分\n{fee_note}"
                               f"你实际扣除：{total}积分\n"
                               f"当前余额：{new_balance}积分\n"
                               f"今日剩余转账次数：{remaining}次")]
            return True, msg, (chain, should_remind)

        ok, msg, data = await self._tx(fn)
        if is_private:
            yield event.plain_result(msg)
        elif ok and data and data[0]:
            yield event.chain_result(data[0])
        else:
            yield event.plain_result(msg)
        # 事务外发送消费达标提醒（与其它玩法保持一致）
        if ok and data and data[1]:
            try:
                yield event.plain_result(
                )
            except Exception:
                pass

    # ============================================================
    #  功能：银行系统
    # ============================================================
    async def _get_bank(self, session, user_id: str):
        """查询银行账户（事务内调用），返回 (活期余额, 累计利息) 或 None。"""
        row = (await session.execute(text(
            "SELECT current_balance, total_interest FROM bank_accounts WHERE user_id=:u"
        ), {"u": user_id})).first()
        return row

    @filter.command("开户")
    async def bank_open(self, event: AstrMessageEvent):
        """/开户 —— 开通银行账户（免费），享受每日活期利息"""
        ok_gate, msg_gate = await self._check_group_gate(event, "开户")
        if not ok_gate:
            yield event.plain_result(msg_gate)
            return
        user_id = str(event.get_sender_id()).strip()

        async def fn(session):
            await self._enforce_cooldown(session, user_id)
            await self._ensure_user(session, user_id)
            if await self._get_bank(session, user_id):
                raise _BizError("🏦 你已经开过户啦，直接 /存钱 就行喵~")
            await session.execute(text(
                "INSERT INTO bank_accounts(user_id, current_balance, total_interest) "
                "VALUES(:u, 0, 0)"
            ), {"u": user_id})
            return True, (
                "🏦 银行开户成功！\n"
                f"活期利率：{self.CURRENT_INTEREST_RATE:.0%}/天\n"
                "每日结算自动到账"
            ), None

        _, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    def _parse_bank_amount(self, args: list) -> Optional[int]:
        """解析存/取金额：取第一个纯数字参数，无效返回 None。"""
        for tok in args:
            if tok.isdigit():
                return int(tok)
        return None

    @filter.command("存钱")
    async def bank_deposit(self, event: AstrMessageEvent):
        """/存钱 [积分] —— 将钱包积分存入银行活期账户"""
        ok_gate, msg_gate = await self._check_group_gate(event, "存钱")
        if not ok_gate:
            yield event.plain_result(msg_gate)
            return
        user_id = str(event.get_sender_id()).strip()
        args = self._strip_command(event, "存钱").split()
        amount = self._parse_bank_amount(args)
        deposit_all = amount is None  # 不带金额 = 默认存入全部普通余额
        if amount is not None and amount <= 0:
            yield event.plain_result("❌ 请输入有效的存入金额，如：/存钱 100")
            return

        async def fn(session):
            remaining = await self._enforce_cooldown(session, user_id)
            if remaining > 0:
                raise _BizError(f"操作太频繁啦，请 {remaining} 秒后再试喵~")
            if not await self._get_bank(session, user_id):
                raise _BizError("🏦 你还没有银行账户，先发送 /开户 开通喵~")
            # 存银行只能用普通余额（贷款积分不可存银行）
            row = (await session.execute(text(
                "SELECT balance, loan_balance FROM users WHERE user_id=:u"
            ), {"u": user_id})).first()
            normal, loan_bal = int(row[0]), int(row[1])
            # 注意：amount 是外层闭包变量，此处不得对它赋值，否则会变成 fn 局部变量导致 UnboundLocalError
            if deposit_all:
                deposit_amt = normal
                if deposit_amt <= 0:
                    hint = (f"（贷款余额 {loan_bal} 积分不可用于存银行）"
                            if loan_bal > 0 else "当前没有积分可存喵~")
                    raise _BizError(f"❌ 普通余额为 0，没得存{hint}")
            else:
                deposit_amt = amount
            if normal < deposit_amt:
                hint = (f"\n（贷款余额 {loan_bal} 积分不可用于存银行）"
                        if loan_bal > 0 else "")
                raise _BizError(
                    f"❌ 积分不足！需要 {deposit_amt} 积分，当前普通余额：{normal}积分{hint}")
            # 钱包原子扣款（只用普通余额），存入银行
            await self._add_points(session, user_id, -deposit_amt, "bank_deposit",
                                   earned=0, spent=deposit_amt, force_normal=True)
            await session.execute(text(
                "UPDATE bank_accounts SET current_balance=current_balance+:a WHERE user_id=:u"
            ), {"a": deposit_amt, "u": user_id})
            # 银行流水：存款
            await session.execute(text(
                "INSERT INTO bank_transactions(user_id, type, amount, create_time) "
                "VALUES(:u, 'deposit', :a, :t)"
            ), {"u": user_id, "a": deposit_amt, "t": time.time()})
            bank = await self._get_bank(session, user_id)
            estimate = int(bank[0] * self.CURRENT_INTEREST_RATE)
            return True, (
                f"💰 存入 {deposit_amt} 积分到活期账户成功！\n"
                f"当前活期余额：{bank[0]}积分\n"
                f"预计每日收益：{estimate}积分"
            ), None

        _, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    @filter.command("取钱")
    async def bank_withdraw(self, event: AstrMessageEvent):
        """/取钱 [积分] —— 从银行活期账户取出积分到钱包"""
        ok_gate, msg_gate = await self._check_group_gate(event, "取钱")
        if not ok_gate:
            yield event.plain_result(msg_gate)
            return
        user_id = str(event.get_sender_id()).strip()
        args = self._strip_command(event, "取钱").split()
        amount = self._parse_bank_amount(args)
        if amount is None or amount <= 0:
            yield event.plain_result("❌ 请输入有效的取出金额，如：/取钱 100")
            return

        async def fn(session):
            remaining = await self._enforce_cooldown(session, user_id)
            if remaining > 0:
                raise _BizError(f"操作太频繁啦，请 {remaining} 秒后再试喵~")
            bank = await self._get_bank(session, user_id)
            if not bank:
                raise _BizError("🏦 你还没有银行账户，先发送 /开户 开通喵~")
            if bank[0] < amount:
                raise _BizError(f"❌ 银行余额不足！当前活期余额：{bank[0]}积分")
            # 银行扣款（余额条件防并发超取），转入钱包
            result = await session.execute(text(
                "UPDATE bank_accounts SET current_balance=current_balance-:a "
                "WHERE user_id=:u AND current_balance-:a >= 0"
            ), {"a": amount, "u": user_id})
            if result.rowcount != 1:
                raise _BizError(f"❌ 银行余额不足！当前活期余额：{bank[0]}积分")
            await self._add_points(session, user_id, amount, "bank_withdraw",
                                   earned=amount, spent=0)
            # 银行流水：取款
            await session.execute(text(
                "INSERT INTO bank_transactions(user_id, type, amount, create_time) "
                "VALUES(:u, 'withdraw', :a, :t)"
            ), {"u": user_id, "a": amount, "t": time.time()})
            bank = await self._get_bank(session, user_id)
            estimate = int(bank[0] * self.CURRENT_INTEREST_RATE)
            return True, (
                f"💵 取出 {amount} 积分到钱包成功！\n"
                f"当前活期余额：{bank[0]}积分\n"
                f"预计每日收益：{estimate}积分"
            ), None

        _, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    @filter.command("我的银行")
    async def bank_overview(self, event: AstrMessageEvent):
        """/我的银行 —— 查看银行账户总览"""
        ok_gate, msg_gate = await self._check_group_gate(event, "我的银行")
        if not ok_gate:
            yield event.plain_result(msg_gate)
            return
        user_id = str(event.get_sender_id()).strip()

        async def fn(session):
            await self._enforce_cooldown(session, user_id)
            bank = await self._get_bank(session, user_id)
            if not bank:
                raise _BizError("🏦 你还没有银行账户，先发送 /开户 开通喵~")
            estimate = int(bank[0] * self.CURRENT_INTEREST_RATE)
            return True, (
                "🏦 银行账户总览\n"
                f"💳 活期余额：{bank[0]}积分\n"
                f"📈 今日活期收益：{estimate}积分\n"
                f"💰 累计利息：{bank[1]}积分"
            ), None

        _, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    async def _daily_bank_settlement(self):
        """每日凌晨 0 点银行结算：玩家活期利息 + 管理员额外收益（独立发放）。

        - 玩家利息 = 活期余额 × CURRENT_INTEREST_RATE（向下取整，全额到账钱包）
        - 管理员额外收益 = 每个账户活期余额 × ADMIN_EXTRA_RATE 的总和，流入 fee_receiver
        """
        if not self.feature_flags.get("enable_bank", True):
            return
        rate = self.CURRENT_INTEREST_RATE
        extra_rate = self.ADMIN_EXTRA_RATE
        receiver = self.FEE_RECEIVER

        async def fn(session):
            rows = (await session.execute(text(
                "SELECT user_id, current_balance FROM bank_accounts WHERE current_balance > 0"
            ))).all()
            total_interest = 0
            total_admin_extra = 0
            for uid, balance in rows:
                # 玩家利息：全额到账钱包，累计进 total_interest
                interest = int(int(balance) * rate)
                if interest > 0:
                    await self._add_points(session, str(uid), interest, "bank_interest",
                                           earned=interest, spent=0)
                    await session.execute(text(
                        "UPDATE bank_accounts SET total_interest=total_interest+:i "
                        "WHERE user_id=:u"
                    ), {"i": interest, "u": str(uid)})
                    # 银行流水：利息
                    await session.execute(text(
                        "INSERT INTO bank_transactions(user_id, type, amount, create_time) "
                        "VALUES(:u, 'interest', :a, :t)"
                    ), {"u": str(uid), "a": interest, "t": time.time()})
                    total_interest += interest
                # 管理员额外收益：独立发放，不影响玩家利息
                admin_extra = int(int(balance) * extra_rate)
                if admin_extra > 0:
                    total_admin_extra += admin_extra
            # 银行利息同额注入系统钱包（玩家 +N，系统钱包 +N）
            if total_interest > 0:
                await self._wallet_inflow_s(
                    session, total_interest, "bank_interest",
                    f"银行日结利息同额注入（{len(rows)} 户）"
                )
            # 汇总一次性发放给手续费接收账户（与收税同源，缺省第一个管理员）
            if total_admin_extra > 0 and receiver:
                await self._add_points(session, receiver, total_admin_extra, "bank_admin_extra",
                                       earned=total_admin_extra, spent=0)
                # 银行流水：管理员额外收益（总额一条）
                await session.execute(text(
                    "INSERT INTO bank_transactions(user_id, type, amount, create_time) "
                    "VALUES(:u, 'admin_extra', :a, :t)"
                ), {"u": receiver, "a": total_admin_extra, "t": time.time()})
            return True, "ok", (total_interest, total_admin_extra if receiver else 0)

        ok, _, data = await self._tx(fn)
        if not ok or not data or (data[0] <= 0 and data[1] <= 0):
            return
        broadcast_chain = [Plain(
            "🏦 银行日结完成！\n"
            f"共发放玩家利息：{data[0]} 积分（同额注入系统钱包）\n"
            f"管理员额外收益：{data[1]} 积分"
        )]
        # 广播到所有已开启玩法的群（与排行榜播报同一群来源）
        try:
            async with self._session() as session:
                groups = (await session.execute(text(
                    "SELECT group_id, platform_id FROM group_settings WHERE enabled=1"
                ))).all()
        except Exception:
            groups = []
        platform_ids = []
        try:
            manager = getattr(self.context, "platform_manager", None)
            if manager and hasattr(manager, "get_insts"):
                platform_ids = [str(p.meta().id) for p in manager.get_insts() if p.meta().id]
            elif manager and hasattr(manager, "platform_insts"):
                platform_ids = [str(p.meta().id) for p in manager.platform_insts if p.meta().id]
        except Exception:
            platform_ids = []
        for group_id, platform_id in groups:
            if not group_id:
                continue
            targets = [str(platform_id)] if platform_id else platform_ids
            for target_platform in targets:
                try:
                    await self._send_group_chain(target_platform, str(group_id), broadcast_chain)
                except Exception:
                    self.logger.exception(f"银行日结播报发送失败：{group_id}")

    async def _daily_bank_report(self):
        """每晚指定时间发送银行日结流水 + 系统总流水报告到配置的群聊。"""
        if not self.feature_flags.get("enable_bank", True):
            return
        if not self.BANK_REPORT_GROUP:
            return  # 未配置发送群聊则不发送
        # 统计窗口：北京时间今日 0 点 ~ 明日 0 点（银行流水与积分流水均存时间戳）
        day_start = datetime.now(TZ).replace(hour=0, minute=0, second=0, microsecond=0)
        day_end = day_start + timedelta(days=1)
        t0, t1 = day_start.timestamp(), day_end.timestamp()
        today = day_start.date().isoformat()

        async def fn(session):
            # ===== 银行流水（bank_transactions 按类型汇总今日记录）=====
            bank_stats = {"deposit": (0, 0), "withdraw": (0, 0),
                          "interest": (0, 0), "admin_extra": (0, 0)}
            rows = (await session.execute(text(
                "SELECT type, COUNT(*), COALESCE(SUM(amount),0) FROM bank_transactions "
                "WHERE create_time >= :t0 AND create_time < :t1 GROUP BY type"
            ), {"t0": t0, "t1": t1})).all()
            for rtype, cnt, total in rows:
                if rtype in bank_stats:
                    bank_stats[rtype] = (int(cnt), int(total))
            # 当前银行总存款与开户数
            row = (await session.execute(text(
                "SELECT COALESCE(SUM(current_balance),0), COUNT(*) FROM bank_accounts"
            ))).first()
            total_bank, total_users = int(row[0]), int(row[1])
            # ===== 系统总流水（point_transactions 今日，剔除银行存取避免重复计入）=====
            row = (await session.execute(text(
                "SELECT COALESCE(SUM(amount),0) FROM point_transactions "
                "WHERE amount > 0 AND create_time >= :t0 AND create_time < :t1 "
                "AND operation != 'bank_withdraw'"
            ), {"t0": t0, "t1": t1})).first()
            total_income = int(row[0])
            row = (await session.execute(text(
                "SELECT COALESCE(SUM(-amount),0) FROM point_transactions "
                "WHERE amount < 0 AND create_time >= :t0 AND create_time < :t1 "
                "AND operation != 'bank_deposit'"
            ), {"t0": t0, "t1": t1})).first()
            total_expense = int(row[0])
            # 今日转账手续费（v4.23.0 起流入系统钱包，从钱包流水统计）
            row = (await session.execute(text(
                "SELECT COALESCE(SUM(amount),0) FROM system_wallet_log "
                "WHERE source='transfer_fee' AND type='inflow' "
                "AND create_time >= :t0 AND create_time < :t1"
            ), {"t0": t0, "t1": t1})).first()
            transfer_fee_total = int(row[0])
            # 今日税收（用户 tax 流水）
            row = (await session.execute(text(
                "SELECT COALESCE(SUM(-amount),0) FROM point_transactions "
                "WHERE operation='tax' AND create_time >= :t0 AND create_time < :t1"
            ), {"t0": t0, "t1": t1})).first()
            tax_total = int(row[0])
            # 系统总积分池 = 所有用户钱包余额 + 银行存款总和
            row = (await session.execute(text(
                "SELECT COALESCE(SUM(balance),0) FROM users"
            ))).first()
            total_user_balance = int(row[0])
            system_total_pool = total_user_balance + total_bank
            return True, "ok", {
                "deposit": bank_stats["deposit"], "withdraw": bank_stats["withdraw"],
                "interest": bank_stats["interest"], "admin_extra": bank_stats["admin_extra"],
                "total_bank": total_bank, "total_users": total_users,
                "income": total_income, "expense": total_expense,
                "fee": transfer_fee_total, "tax": tax_total,
                "pool": system_total_pool,
            }

        ok, _, data = await self._tx(fn)
        if not ok or not data:
            return
        dep_cnt, dep_total = data["deposit"]
        wd_cnt, wd_total = data["withdraw"]
        it_cnt, it_total = data["interest"]
        ae_cnt, ae_total = data["admin_extra"]
        net_flow = data["income"] - data["expense"]
        msg = (
            "📊 【银行日结流水】\n"
            f"日期：{today}\n"
            "─────────────\n"
            f"💳 今日存款：{dep_total} 积分（{dep_cnt}笔）\n"
            f"💸 今日取款：{wd_total} 积分（{wd_cnt}笔）\n"
            f"📈 今日发放利息：{it_total} 积分\n"
            f"💰 管理员额外收益：{ae_total} 积分\n"
            "─────────────\n"
            f"📊 当前银行总存款：{data['total_bank']} 积分\n"
            f"👥 银行总用户数：{data['total_users']} 人\n\n"
            "─────────────\n"
            "💰 【系统总流水】\n"
            f"📈 总收入：{data['income']} 积分（签到/闯关/速算/掷骰/活跃/炸弹等）\n"
            f"💸 总支出：{data['expense']} 积分（转盘/BOSS/大乐透/卧底/抽卡/转账等）\n"
            f"📊 净流通：{net_flow:+d} 积分\n"
            f"💳 转账手续费：{data['fee']} 积分\n"
            f"📊 税收：{data['tax']} 积分\n"
            "─────────────\n"
            f"📊 系统总积分池：{data['pool']} 积分"
        )
        broadcast_chain = [Plain(msg)]
        for group_id in self.BANK_REPORT_GROUP:
            try:
                await self._send_group_chain("", str(group_id), broadcast_chain)
            except Exception:
                self.logger.exception(f"银行流水报告发送失败：{group_id}")

    # ============================================================
    #  功能：每日红包（拼手气）
    # ============================================================
    async def _broadcast_to_group(self, group_id: str, chain, platform_id: str = ""):
        """向指定群广播消息：优先用传入的 platform_id，失败或为空时向所有平台实例 fan-out。"""
        tried: list[str] = []
        if platform_id:
            tried.append(str(platform_id))
        for pid in await self._get_platform_ids():
            if pid and pid not in tried:
                tried.append(pid)
        if not tried:
            tried = [""]
        for target_platform in tried:
            try:
                await self._send_group_chain(target_platform, str(group_id), chain)
                return True
            except Exception:
                self.logger.exception(f"群消息发送失败（平台 {target_platform}）：{group_id}")
        return False

    async def _notify_admins(self, text: str):
        """私聊通知所有配置的管理员QQ。"""
        admin_platforms = await self._get_platform_ids() or [""]
        for admin_qq in self.ADMIN_QQ:
            for target_platform in admin_platforms:
                try:
                    await self._send_private(target_platform, str(admin_qq), text)
                    break
                except Exception:
                    self.logger.exception(f"管理员通知发送失败：{admin_qq}")

    async def _schedule_red_packet(self):
        """为今天生成红包随机触发时间（在配置窗口内），按每日次数生成多个不重叠时间点。

        时间点之间至少间隔一个红包时限（不重叠），窗口已过则跳过；
        调度完成后私聊通知管理员具体的发放时间。
        """
        if not self.feature_flags.get("enable_red_packet", True):
            return
        if not self.RED_PACKET_GROUP:
            self.logger.warning("红包未配置发送群聊（red_packet_group），今日红包不发放")
            return
        if self.RED_PACKET_COUNT < 1 or self.RED_PACKET_TOTAL < self.RED_PACKET_COUNT:
            self.logger.warning("红包配置无效：总额需≥份数（每份至少1积分），今日红包跳过")
            await self._notify_admins(
                "⚠️ 每日红包配置无效：红包总额需≥份数（每份至少1积分），今日红包已跳过")
            return
        # 当日调度已持久化过：重启/重载后只恢复未发放的时间点，不重新随机、不重复通知
        now_d = datetime.now(TZ)
        today = now_d.date().isoformat()
        async def load_schedule(session):
            row = (await session.execute(text(
                "SELECT times FROM red_packet_schedule WHERE date=:d"
            ), {"d": today})).first()
            return True, "ok", (str(row[0]) if row else None)
        ok, _, saved = await self._tx(load_schedule)
        if ok and saved:
            restored = 0
            for t in saved.split(","):
                t = t.strip()
                if not t:
                    continue
                try:
                    run_at = datetime.fromisoformat(t)
                except ValueError:
                    continue
                if run_at.tzinfo is None:
                    run_at = run_at.replace(tzinfo=TZ)
                if run_at <= now_d:
                    continue  # 已发放/已过期的时间点不恢复
                self._scheduler.add_job(
                    self._send_red_packet,
                    DateTrigger(run_date=run_at, timezone=TZ),
                    id=f"red_packet_send_{today}_{restored}", replace_existing=True,
                )
                restored += 1
            self.logger.info(f"今日红包调度已存在，恢复 {restored} 个未发放时间点")
            return
        sh, sm, eh, em = self.RED_PACKET_WINDOW
        now = datetime.now(TZ)
        start = now.replace(hour=sh, minute=sm, second=0, microsecond=0)
        end = now.replace(hour=eh, minute=em, second=0, microsecond=0)
        if end <= start:
            self.logger.warning("红包时间窗口配置异常（结束早于开始），今日红包跳过")
            await self._notify_admins("⚠️ 每日红包时间窗口配置异常（结束早于开始），今日红包已跳过")
            return
        window_start = max(start, now)
        if window_start >= end:
            return  # 今日窗口已过
        total_sec = (end - window_start).total_seconds()
        times = self.RED_PACKET_DAILY_TIMES
        # 每个红包至少占用 时限+2分钟 的窗口，超出则削减次数防止重叠
        min_span = (self.RED_PACKET_TIMEOUT + 2) * 60
        times = max(1, min(times, int(total_sec // min_span) or 1))
        # 均分窗口成 times 段，每段内随机一个时间点；
        # 段尾预留一个完整时限，保证相邻两场红包不会同时进行
        seg = total_sec / times
        run_times = []
        for i in range(times):
            seg_start = window_start + timedelta(seconds=seg * i)
            seg_end = seg_start + timedelta(seconds=seg - self.RED_PACKET_TIMEOUT * 60)
            if seg_end <= seg_start:
                seg_end = seg_start + timedelta(seconds=30)
            run_at = seg_start + timedelta(seconds=random.uniform(0, (seg_end - seg_start).total_seconds()))
            run_times.append(run_at)
            self._scheduler.add_job(
                self._send_red_packet,
                DateTrigger(run_date=run_at, timezone=TZ),
                id=f"red_packet_send_{today}_{i}", replace_existing=True,
            )
        # 持久化今日调度：重启/重载后据此恢复，不重新随机不重复通知
        async def save_schedule(session):
            await session.execute(text(
                "INSERT OR REPLACE INTO red_packet_schedule(date, times) VALUES(:d, :t)"
            ), {"d": today, "t": ",".join(t.isoformat() for t in run_times)})
            await session.execute(text(
                "DELETE FROM red_packet_schedule WHERE date < :d"
            ), {"d": today})
            return True, "ok", None
        await self._tx(save_schedule)
        times_text = "、".join(t.strftime("%H:%M") for t in run_times)
        self.logger.info(f"今日红包已调度：{times} 次（{times_text}）")
        # 通知管理员具体的发放时间
        try:
            await self._notify_admins(
                "🧧 今日红包已排定！\n"
                f"预计发放时间：{times_text}\n"
                f"发送群：{self.RED_PACKET_GROUP}\n"
                f"共 {times} 场，每场 {self.RED_PACKET_TOTAL} 积分 / {self.RED_PACKET_COUNT} 份"
            )
        except Exception:
            self.logger.exception("红包调度通知发送失败")

    async def _send_red_packet(self):
        """在指定群发送拼手气红包，并注册超时结算任务。"""
        if not self.RED_PACKET_GROUP:
            return
        # 系统钱包出资模式：先扣资金池，余额不足则取消本场并全群通知
        if self.REDPACKET_FROM_WALLET:
            total_pre = self.RED_PACKET_TOTAL
            remark = f"每日红包 {datetime.now(TZ).strftime('%m-%d %H:%M')}"
            if not await self.wallet_outflow(total_pre, "daily_redpacket", remark):
                self.logger.warning(
                    f"系统钱包余额不足（需 {total_pre}），本场每日红包取消"
                )
                cancel_chain = [Plain(
                    f"😔 系统钱包余额不足，本场红包（{total_pre}积分）取消了…\n"
                    "期待钱包回血后再来喵~"
                )]
                try:
                    await self._broadcast_to_group(
                        str(self.RED_PACKET_GROUP), cancel_chain
                    )
                except Exception:
                    self.logger.exception("红包取消通知发送失败")
                try:
                    await self._notify_admins(
                        f"⚠️ 系统钱包余额不足（需 {total_pre} 积分），"
                        "本场每日红包已取消。可用 /系统 存 积分 充值资金池"
                    )
                except Exception:
                    self.logger.exception("红包取消管理员通知失败")
                return
        # 保险：上一场红包尚未结束时跳过本场（正常调度已保证不重叠）
        async with self._red_packet_lock:
            if self._red_packet and not self._red_packet["finished"]:
                self.logger.warning("上一场红包尚未结束，本场红包跳过")
                return
        total, count = self.RED_PACKET_TOTAL, self.RED_PACKET_COUNT
        packet_id = f"rp{int(time.time() * 1000)}"
        expire_ts = time.time() + self.RED_PACKET_TIMEOUT * 60
        async def fn(session):
            await session.execute(text(
                "INSERT INTO red_packet_log(packet_id, total_amount, total_count, "
                "remain_count, remain_amount, status, create_time) "
                "VALUES(:p, :t, :c, :c, :t, 'active', :time)"
            ), {"p": packet_id, "t": total, "c": count, "time": time.time()})
            return True, "ok", None
        await self._tx(fn)
        async with self._red_packet_lock:
            self._red_packet = {
                "packet_id": packet_id, "group_id": str(self.RED_PACKET_GROUP),
                "total_count": count, "remain_count": count,
                "remain_amount": total, "claimed": {}, "max": (None, 0),
                "expire": expire_ts, "finished": False,
            }
        chain = [Plain(
            f"🧧 红包来啦！总额{total}积分，共{count}份，拼手气！\n"
            "发送 抢 参与！\n\n"
            f"💡 剩余：{count}份 | 已抢：0份"
        )]
        try:
            sent_ok = await self._broadcast_to_group(str(self.RED_PACKET_GROUP), chain)
            if not sent_ok:
                raise RuntimeError("所有平台均发送失败")
        except Exception:
            self.logger.exception("红包消息发送失败")
            async with self._red_packet_lock:
                self._red_packet = None
            # 落库标记本场未发出，避免日志里留一条永远 active 的假红包
            async def fn_send_fail(session):
                await session.execute(text(
                    "UPDATE red_packet_log SET status='send_failed' WHERE packet_id=:p"
                ), {"p": packet_id})
                return True, "ok", None
            await self._tx(fn_send_fail)
            await self._notify_admins("⚠️ 今日红包发送失败，请检查插件日志")
            return
        # 注册超时结算（到点回收剩余积分）
        self._scheduler.add_job(
            self._finish_red_packet,
            DateTrigger(run_date=datetime.fromtimestamp(expire_ts, TZ), timezone=TZ),
            id=f"red_packet_end_{packet_id}", replace_existing=True,
        )

    # ==================== 群友发红包 ====================
    @filter.command("发红包")
    @filter.event_message_type(EventMessageType.GROUP_MESSAGE)
    async def user_send_red_packet(self, event: AstrMessageEvent):
        """群友自掏腰包发积分红包，其他人发送「抢」参与。"""
        ok_gate, msg_gate = await self._check_group_gate(event, "发红包")
        if not ok_gate:
            yield event.plain_result(msg_gate)
            return
        
        user_id = str(event.get_sender_id() or "").strip()
        group_id = str(event.get_group_id() or "").strip()
        platform_id = event.get_platform_id()
        group_key = f"{platform_id}_{group_id}"
        
        args_text = self._strip_command(event, "发红包").strip()
        parts = args_text.split()
        
        if len(parts) < 2:
            yield event.plain_result("❌ 格式：/发红包 [总积分] [份数]\n示例：/发红包 200 5")
            return
        
        try:
            total = int(parts[0])
            count = int(parts[1])
        except ValueError:
            yield event.plain_result("❌ 总积分和份数必须是数字喵~")
            return
        
        if total < self.USER_RED_PACKET_MIN or total > self.USER_RED_PACKET_MAX:
            yield event.plain_result(f"❌ 红包总积分范围：{self.USER_RED_PACKET_MIN}-{self.USER_RED_PACKET_MAX}")
            return
        
        if count < 1 or count > total:
            yield event.plain_result(f"❌ 份数范围：1-{total}（每份至少1积分）")
            return
        
        # 检查该群是否已有活跃红包（占位防并发双发）
        lock = self._user_red_packet_locks.setdefault(group_key, asyncio.Lock())
        rp_busy = False
        async with lock:
            if group_key in self._user_red_packets and not self._user_red_packets[group_key]["finished"]:
                rp_busy = True
            else:
                # finished=True 的占位条目：堵住检查与写入状态之间的并发窗口
                self._user_red_packets[group_key] = {"finished": True}
        if rp_busy:
            yield event.plain_result("❌ 本群还有红包未抢完，请等待结束后再发喵~")
            return
        
        # 扣积分并创建红包
        async def fn(session):
            balance = await self._balance(session, user_id)
            if balance < total:
                return False, f"❌ 积分不足喵~ 当前余额：{balance}积分", None
            
            await self._add_points(session, user_id, -total, "send_user_redpacket",
                                   earned=0, spent=total)
            
            packet_id = f"user_rp_{int(time.time()*1000)}_{user_id}"
            await session.execute(text(
                "INSERT INTO red_packet_log(packet_id, sender_id, total_amount, total_count, "
                "remain_count, remain_amount, status, group_id, platform_id, create_time) "
                "VALUES(:pid, :sid, :ta, :tc, :rc, :ra, :st, :gid, :plat, :time)"
            ), {
                "pid": packet_id, "sid": user_id, "ta": total, "tc": count,
                "rc": count, "ra": total, "st": "active", "gid": group_id,
                "plat": platform_id, "time": time.time()
            })
            return True, packet_id, None
        
        ok, packet_id, _ = await self._tx(fn)
        if not ok:
            # 创建失败：撤掉占位条目
            async with lock:
                self._user_red_packets.pop(group_key, None)
            yield event.plain_result(packet_id)
            return
        
        # 创建红包状态
        expire_ts = time.time() + self.USER_RED_PACKET_TIMEOUT
        async with lock:
            self._user_red_packets[group_key] = {
                "packet_id": packet_id,
                "sender_id": user_id,
                "group_id": group_id,
                "platform_id": platform_id,
                "remain_count": count,
                "remain_amount": total,
                "claimed": {},
                "max": ("", 0),
                "expire": expire_ts,
                "finished": False,
            }
        
        # 注册超时结算
        self._scheduler.add_job(
            lambda: self._finish_user_red_packet(group_key),
            DateTrigger(run_date=datetime.fromtimestamp(expire_ts, TZ), timezone=TZ),
            id=f"user_red_packet_end_{packet_id}", replace_existing=True,
        )
        
        yield event.chain_result([
            Plain("🧧 "), At(qq=str(user_id)),
            Plain(f" 发了 {total} 积分红包，共 {count} 份！\n💬 发送「抢」参与！\n⏱️ {self.USER_RED_PACKET_TIMEOUT}秒后超时回收")
        ])

    @filter.event_message_type(EventMessageType.GROUP_MESSAGE)
    @filter.regex(re.compile(r"^抢\s*$"))
    async def grab_red_packet(self, event: AstrMessageEvent):
        """群内发送「抢」参与红包：每人限抢一次，拼手气随机分配。支持系统红包和群友红包。"""
        user_id = str(event.get_sender_id() or "").strip()
        group_id = str(event.get_group_id() or "").strip()
        platform_id = event.get_platform_id()
        group_key = f"{platform_id}_{group_id}"
        
        if not user_id or not group_id:
            return
        
        # 优先检查群友红包
        lock = self._user_red_packet_locks.get(group_key)
        user_rp_handled = False
        finish_needed = False
        if lock:
            async with lock:
                rp = self._user_red_packets.get(group_key)
                if rp and not rp["finished"] and time.time() < rp["expire"] and rp["remain_count"] > 0:
                    # 抢群友红包
                    if user_id in rp["claimed"]:
                        yield event.plain_result("你已经抢过这个红包啦喵~")
                        return
                    
                    # 拼手气二倍均值法
                    if rp["remain_count"] == 1:
                        amount = rp["remain_amount"]
                    else:
                        avg2 = rp["remain_amount"] * 2 // rp["remain_count"]
                        amount = random.randint(1, max(1, avg2 - 1))
                    
                    rp["remain_count"] -= 1
                    rp["remain_amount"] -= amount
                    rp["claimed"][user_id] = amount
                    if amount > rp["max"][1]:
                        rp["max"] = (user_id, amount)
                    
                    is_last = rp["remain_count"] <= 0
                    packet_id = rp["packet_id"]
                    state = (rp["remain_count"], rp["remain_amount"])
                    hint = f"💡 剩余：{rp['remain_count']}份 | 已抢：{len(rp['claimed'])}份"
                    
                    # 锁外落库
                    async def fn(session):
                        await session.execute(text(
                            "INSERT INTO red_packet_records(packet_id, user_id, amount, create_time) "
                            "VALUES(:p, :u, :a, :time)"
                        ), {"p": packet_id, "u": user_id, "a": amount, "time": time.time()})
                        await session.execute(text(
                            "UPDATE red_packet_log SET remain_count=:rc, remain_amount=:ra "
                            "WHERE packet_id=:p"
                        ), {"rc": state[0], "ra": state[1], "p": packet_id})
                        await self._add_points(session, user_id, amount, "grab_user_redpacket",
                                               earned=amount, spent=0)
                        return True, "ok", None
                    
                    ok, _, _ = await self._tx(fn)
                    if not ok:
                        # 事务失败：回滚内存状态，不发假到账消息
                        rp["remain_count"] += 1
                        rp["remain_amount"] += amount
                        rp["claimed"].pop(user_id, None)
                        yield event.plain_result("❌ 红包领取失败，积分未入账，请稍后再试喵~")
                        return
                    yield event.chain_result([Plain("🎉 恭喜 "), At(qq=str(user_id)),
                                              Plain(f" 抢到 {amount} 积分！\n{hint}")])
                    
                    user_rp_handled = True
                    finish_needed = ok and is_last
            if user_rp_handled:
                # 锁外结算，避免同锁重入死锁
                if finish_needed:
                    await self._finish_user_red_packet(group_key)
                return

        # 系统红包（原逻辑）
        packet_id = None
        state = None
        amount = None
        is_last = False
        hint = ""
        async with self._red_packet_lock:
            rp = self._red_packet
            if not rp or rp["finished"]:
                return
            if str(event.get_group_id() or "") != rp["group_id"]:
                return
            if time.time() >= rp["expire"] or rp["remain_count"] <= 0:
                return
            if user_id in rp["claimed"]:
                yield event.plain_result("你已经抢过这个红包啦喵~")
                return
            
            if rp["remain_count"] == 1:
                amount = rp["remain_amount"]
            else:
                avg2 = rp["remain_amount"] * 2 // rp["remain_count"]
                amount = random.randint(1, max(1, avg2 - 1))
            
            rp["remain_count"] -= 1
            rp["remain_amount"] -= amount
            rp["claimed"][user_id] = amount
            if amount > rp["max"][1]:
                rp["max"] = (user_id, amount)
            is_last = rp["remain_count"] <= 0
            packet_id = rp["packet_id"]
            state = (rp["remain_count"], rp["remain_amount"])
            hint = f"💡 剩余：{rp['remain_count']}份 | 已抢：{len(rp['claimed'])}份"
        
        async def fn(session):
            await session.execute(text(
                "INSERT INTO red_packet_records(packet_id, user_id, amount, create_time) "
                "VALUES(:p, :u, :a, :time)"
            ), {"p": packet_id, "u": user_id, "a": amount, "time": time.time()})
            await session.execute(text(
                "UPDATE red_packet_log SET remain_count=:rc, remain_amount=:ra "
                "WHERE packet_id=:p"
            ), {"rc": state[0], "ra": state[1], "p": packet_id})
            await self._add_points(session, user_id, amount, "red_packet",
                                   earned=amount, spent=0)
            return True, "ok", None
        
        ok, _, _ = await self._tx(fn)
        yield event.chain_result([Plain("🎉 恭喜 "), At(qq=str(user_id)),
                                  Plain(f" 抢到 {amount} 积分！\n{hint}")])
        if ok and is_last:
            await self._finish_red_packet()

    async def _finish_red_packet(self):
        """结束红包：更新状态、结算剩余积分回收并播报手气王。"""
        async with self._red_packet_lock:
            rp = self._red_packet
            if not rp or rp["finished"]:
                return
            rp["finished"] = True
            self._red_packet = None
        async def fn(session):
            await session.execute(text(
                "UPDATE red_packet_log SET status='ended', remain_count=:rc, remain_amount=:ra "
                "WHERE packet_id=:p"
            ), {"rc": rp["remain_count"], "ra": rp["remain_amount"], "p": rp["packet_id"]})
            return True, "ok", None
        await self._tx(fn)
        try:
            self._scheduler.remove_job(f"red_packet_end_{rp['packet_id']}")
        except Exception:
            pass
        sent = len(rp["claimed"])
        recycled = rp["remain_amount"]
        head = (f"🧧 红包已结束！\n共发出 {sent} 份，"
                + (f"剩余 {recycled} 积分已回收" if recycled > 0 else "红包全部抢完！"))
        chain = [Plain(head)]
        king_id, king_amt = rp["max"]
        if king_id:
            chain.extend([Plain("\n手气王："), At(qq=str(king_id)),
                          Plain(f" 获得 {king_amt} 积分！")])
        try:
            await self._broadcast_to_group(rp["group_id"], chain)
        except Exception:
            self.logger.exception("红包结算播报发送失败")

    async def _finish_user_red_packet(self, group_key: str):
        """结束群友红包：更新状态、剩余积分退回发送者并播报手气王。"""
        lock = self._user_red_packet_locks.get(group_key)
        if not lock:
            return
        
        async with lock:
            rp = self._user_red_packets.get(group_key)
            if not rp or rp["finished"]:
                return
            rp["finished"] = True
            snapshot = dict(rp)
            del self._user_red_packets[group_key]
        
        # 剩余积分退回发送者
        recycled = snapshot["remain_amount"]
        if recycled > 0:
            async def fn(session):
                await session.execute(text(
                    "UPDATE red_packet_log SET status='ended', remain_count=:rc, remain_amount=0 "
                    "WHERE packet_id=:p"
                ), {"rc": 0, "p": snapshot["packet_id"]})
                await self._add_points(session, snapshot["sender_id"], recycled, "redpacket_refund",
                                       earned=recycled, spent=0)
                return True, "ok", None
            await self._tx(fn)
        else:
            async def fn(session):
                await session.execute(text(
                    "UPDATE red_packet_log SET status='ended', remain_count=:rc, remain_amount=:ra "
                    "WHERE packet_id=:p"
                ), {"rc": snapshot["remain_count"], "ra": snapshot["remain_amount"], "p": snapshot["packet_id"]})
                return True, "ok", None
            await self._tx(fn)
        
        try:
            self._scheduler.remove_job(f"user_red_packet_end_{snapshot['packet_id']}")
        except Exception:
            pass
        
        sent = len(snapshot["claimed"])
        head = (f"🧧 红包已结束！\n共发出 {sent} 份，"
                + (f"剩余 {recycled} 积分已退回" if recycled > 0 else "红包全部抢完！"))
        chain = [Plain(head)]
        king_id, king_amt = snapshot["max"]
        if king_id:
            chain.extend([Plain("\n🏆 手气王："), At(qq=str(king_id)),
                          Plain(f" 获得 {king_amt} 积分！")])
        
        try:
            await self._broadcast_to_group(snapshot["group_id"], chain, snapshot["platform_id"])
        except Exception:
            self.logger.exception("群友红包结算播报发送失败")

    # ============================================================
    #  功能：贷款系统
    # ============================================================
    def _calc_loan_interest(self, amount: int, start_ts: float, now_ts: float = None):
        """计算贷款利息，不足一天按一天算，返回 (利息, 已计天数)。"""
        now_ts = now_ts or time.time()
        delta = max(0.0, now_ts - float(start_ts))
        days = int(delta // 86400) + (1 if delta % 86400 > 1e-6 else 0)
        days = max(1, days)
        return int(amount * self.LOAN_INTEREST_RATE * days), days

    async def _ensure_credit(self, session, user_id: str):
        """确保信用记录存在，返回 (score, total_loans, on_time_payments)。"""
        await session.execute(text(
            "INSERT OR IGNORE INTO credit_scores(user_id, score, total_loans, on_time_payments) "
            "VALUES(:u, 0, 0, 0)"
        ), {"u": user_id})
        row = (await session.execute(text(
            "SELECT score, total_loans, on_time_payments FROM credit_scores WHERE user_id=:u"
        ), {"u": user_id})).first()
        return (int(row[0]), int(row[1]), int(row[2])) if row else (0, 0, 0)

    async def _loan_settle_credit(self, session, user_id: str, overdue: bool):
        """贷款结清时的信用处理：按时 +奖励/次数+1；逾期 +惩罚/次数归零。"""
        await self._ensure_credit(session, user_id)
        if overdue:
            await session.execute(text(
                "UPDATE credit_scores SET score=score+:d, on_time_payments=0 "
                "WHERE user_id=:u"
            ), {"d": self.LOAN_CREDIT_PENALTY, "u": user_id})
        else:
            await session.execute(text(
                "UPDATE credit_scores SET score=score+:d, "
                "total_loans=total_loans+1, on_time_payments=on_time_payments+1 "
                "WHERE user_id=:u"
            ), {"d": self.LOAN_CREDIT_REWARD, "u": user_id})

    async def _get_active_loan(self, session, user_id: str):
        """查询用户当前未结清贷款（active 或 overdue），返回行或 None。"""
        return (await session.execute(text(
            "SELECT id, user_id, amount, interest, total_due, paid, days, "
            "loan_days_used, status, start_date, due_date FROM loans "
            "WHERE user_id=:u AND status IN ('active','overdue') ORDER BY id LIMIT 1"
        ), {"u": user_id})).first()

    def _credit_limit(self, on_time: int) -> int:
        """根据按时还款次数计算信用额度。"""
        if on_time >= 5:
            return min(self.LOAN_LIMIT_UPGRADE_3, self.LOAN_MAX_LIMIT)
        if on_time >= 3:
            return min(self.LOAN_LIMIT_UPGRADE_2, self.LOAN_MAX_LIMIT)
        if on_time >= 1:
            return min(self.LOAN_LIMIT_UPGRADE_1, self.LOAN_MAX_LIMIT)
        return min(self.LOAN_INITIAL_LIMIT, self.LOAN_MAX_LIMIT)

    @filter.command("贷款")
    async def loan_apply(self, event: AstrMessageEvent):
        """/贷款 [积分] —— 向银行申请贷款，利息即刻开始计算"""
        ok_gate, msg_gate = await self._check_group_gate(event, "贷款")
        if not ok_gate:
            yield event.plain_result(msg_gate)
            return
        user_id = str(event.get_sender_id()).strip()
        args = self._strip_command(event, "贷款").split()
        amount = int(args[0]) if args and args[0].isdigit() else None
        if amount is None or amount < self.LOAN_MIN:
            yield event.plain_result(f"❌ 单次贷款最低 {self.LOAN_MIN} 积分，如：/贷款 500")
            return

        async def fn(session):
            await self._enforce_cooldown(session, user_id)
            await self._ensure_user(session, user_id)
            score, _, on_time = await self._ensure_credit(session, user_id)
            if score < self.LOAN_CREDIT_THRESHOLD:
                raise _BizError("❌ 信用分过低，无法申请贷款（发送 /我的贷款 查看信用）")
            credit_limit = self._credit_limit(on_time)
            if amount > self.LOAN_MAX:
                raise _BizError(f"❌ 单次贷款最高 {self.LOAN_MAX} 积分")
            if amount > credit_limit:
                raise _BizError(f"❌ 超出信用额度！当前额度：{credit_limit}积分")
            loan = await self._get_active_loan(session, user_id)
            if loan and self.LOAN_PREVENT_MULTIPLE:
                raise _BizError(
                    f"❌ 您已有未还清的贷款，{self.LOAN_DAYS}天内不可再次贷款")
            # 冷却期：最近一次放款后的贷款期限内不能再贷，就算提前还清也一样
            last = (await session.execute(text(
                "SELECT MAX(start_date) FROM loans WHERE user_id=:u"
            ), {"u": user_id})).first()
            if last and last[0] is not None:
                cooldown_end = float(last[0]) + self.LOAN_DAYS * 86400
                if time.time() < cooldown_end:
                    # 管理员豁免标记：/冷却重置 写入的终点 ≥ 当前冷却终点则视为已过
                    reset_ts = await self._get_config_value(
                        session, f"loan_cd_reset_{user_id}", "")
                    if not (reset_ts and reset_ts.replace(".", "", 1).isdigit()
                            and float(reset_ts) >= cooldown_end):
                        remain_sec = cooldown_end - time.time()
                        remain_days = int(remain_sec // 86400) + 1
                        remain_h = int((remain_sec % 86400) // 3600)
                        raise _BizError(
                            f"❌ 贷款冷却中！上一笔贷款 {self.LOAN_DAYS} 天期限结束前"
                            f"（约剩 {remain_days} 天 {remain_h} 小时）不能再申请")
            # 利息即刻开始计算（不足一天按一天算）
            now_ts = time.time()
            interest, days_used = self._calc_loan_interest(amount, now_ts, now_ts)
            total_due = amount + interest
            due_ts = now_ts + self.LOAN_DAYS * 86400
            await session.execute(text(
                "INSERT INTO loans(user_id, amount, interest, total_due, paid, days, "
                "loan_days_used, status, start_date, due_date) "
                "VALUES(:u, :a, :i, :t, 0, :d, :du, 'active', :s, :e)"
            ), {"u": user_id, "a": amount, "i": interest, "t": total_due,
                "d": self.LOAN_DAYS, "du": days_used, "s": now_ts, "e": due_ts})
            # 贷款积分存入贷款余额（不可转账），消费时优先使用
            await session.execute(text(
                "UPDATE users SET loan_balance=loan_balance+:a WHERE user_id=:u"
            ), {"a": amount, "u": user_id})
            await session.execute(text(
                "INSERT INTO point_transactions("
                "user_id, amount, operation, earned, spent, balance_after, create_time) "
                "VALUES(:u, 0, 'loan_apply', :a, 0, :b, :t)"
            ), {"u": user_id, "a": amount,
                "b": await self._balance(session, user_id), "t": time.time()})
            due_str = datetime.fromtimestamp(due_ts, TZ).strftime("%Y-%m-%d %H:%M")
            return True, (
                "🏦 贷款申请成功！\n"
                f"贷款金额：{amount}积分（已存入贷款余额）\n"
                "⚠️ 注意：贷款积分不可转账！\n"
                f"当前额度：{credit_limit}积分\n"
                f"期限：{self.LOAN_DAYS}天\n"
                f"利率：{self.LOAN_INTEREST_RATE:.0%}/天\n"
                "即刻开始计息，不足一天按一天算\n"
                f"当前利息：{interest}积分（已计{days_used}天）\n"
                f"到期应还：{total_due}积分（本金{amount}+利息{interest}）\n"
                f"到期日：{due_str}"
            ), None

        _, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    @filter.command("还款")
    async def loan_repay(self, event: AstrMessageEvent):
        """/还款 —— 一次性还清当前贷款（优先普通余额，不足用贷款余额抵扣）"""
        ok_gate, msg_gate = await self._check_group_gate(event, "还款")
        if not ok_gate:
            yield event.plain_result(msg_gate)
            return
        user_id = str(event.get_sender_id()).strip()

        async def fn(session):
            await self._enforce_cooldown(session, user_id)
            await self._ensure_user(session, user_id)
            loan = await self._get_active_loan(session, user_id)
            if not loan:
                raise _BizError("❌ 您当前没有未还的贷款")
            loan_id, _, principal, _, _, paid, _, _, status, start_ts, _ = loan
            # 重新计算利息（不足一天按一天算）
            current_interest, days_used = self._calc_loan_interest(
                int(principal), float(start_ts))
            total_now = int(principal) + current_interest
            remaining = max(0, total_now - int(paid))
            # 余额：优先普通余额，不足用贷款余额抵扣
            row = (await session.execute(text(
                "SELECT balance, loan_balance FROM users WHERE user_id=:u"
            ), {"u": user_id})).first()
            normal, loan_bal = int(row[0]), int(row[1])
            if normal + loan_bal < remaining:
                raise _BizError(
                    f"❌ 余额不足！需要 {remaining} 积分\n"
                    f"普通余额：{normal}，贷款余额：{loan_bal}")
            from_normal = min(normal, remaining)
            from_loanbal = remaining - from_normal
            if from_normal > 0:
                await session.execute(text(
                    "UPDATE users SET balance=balance-:a, "
                    "total_spent=total_spent+:a WHERE user_id=:u AND balance-:a >= 0"
                ), {"a": from_normal, "u": user_id})
            if from_loanbal > 0:
                await session.execute(text(
                    "UPDATE users SET loan_balance=loan_balance-:a, "
                    "total_spent=total_spent+:a WHERE user_id=:u"
                ), {"a": from_loanbal, "u": user_id})
            # 还款流水
            await session.execute(text(
                "INSERT INTO point_transactions("
                "user_id, amount, operation, earned, spent, balance_after, create_time) "
                "VALUES(:u, :a, 'loan_repay', 0, :s, :b, :t)"
            ), {"u": user_id, "a": -remaining, "s": remaining,
                "b": await self._balance(session, user_id), "t": time.time()})
            # 利息转入管理员账户（与收税/转账手续费同源）
            interest_income = max(0, remaining + int(paid) - int(principal))
            if interest_income > 0 and self.FEE_RECEIVER:
                await self._add_points(session, self.FEE_RECEIVER, interest_income,
                                       "loan_interest_income",
                                       earned=interest_income, spent=0)
            # 更新贷款状态
            await session.execute(text(
                "UPDATE loans SET status='paid', paid=:p, interest=:i2, total_due=:t2, "
                "loan_days_used=:du, closed_date=:c WHERE id=:i"
            ), {"p": total_now, "i2": current_interest, "t2": total_now,
                "du": days_used, "c": time.time(), "i": loan_id})
            overdue = status == "overdue"
            await self._loan_settle_credit(session, user_id, overdue=overdue)
            score, _, on_time = await self._ensure_credit(session, user_id)
            new_limit = self._credit_limit(on_time)
            credit_line = (f"信用分 {self.LOAN_CREDIT_PENALTY}，当前信用分：{score}\n"
                           f"额度已重置，当前信用额度：{new_limit}积分"
                           if overdue else
                           f"信用分 +{self.LOAN_CREDIT_REWARD}，当前信用分：{score}\n"
                           f"当前信用额度：{new_limit}积分")
            return True, (
                "✅ 还款成功！已还清贷款！\n"
                f"实际使用 {days_used} 天，利息 {current_interest} 积分已转入管理员账户\n"
                f"{'⚠️ 逾期还款：' if overdue else ''}{credit_line}"
            ), None

        _, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    @filter.command("我的贷款")
    async def my_loan(self, event: AstrMessageEvent):
        """/我的贷款 —— 查看贷款详情、信用分与额度"""
        ok_gate, msg_gate = await self._check_group_gate(event, "我的贷款")
        if not ok_gate:
            yield event.plain_result(msg_gate)
            return
        user_id = str(event.get_sender_id()).strip()

        async def fn(session):
            await self._enforce_cooldown(session, user_id)
            await self._ensure_user(session, user_id)
            score, total_loans, on_time = await self._ensure_credit(session, user_id)
            credit_limit = self._credit_limit(on_time)
            row = (await session.execute(text(
                "SELECT loan_balance FROM users WHERE user_id=:u"
            ), {"u": user_id})).first()
            loan_bal = int(row[0]) if row else 0
            # 额度升级提示
            if credit_limit >= min(self.LOAN_LIMIT_UPGRADE_3, self.LOAN_MAX_LIMIT):
                upgrade_hint = "额度已满级！"
            elif on_time >= 3:
                upgrade_hint = (f"再按时还款 {max(1, 5 - on_time)} 次可升至"
                                f"{min(self.LOAN_LIMIT_UPGRADE_3, self.LOAN_MAX_LIMIT)}积分")
            elif on_time >= 1:
                upgrade_hint = (f"再按时还款 {max(1, 3 - on_time)} 次可升至"
                                f"{min(self.LOAN_LIMIT_UPGRADE_2, self.LOAN_MAX_LIMIT)}积分")
            else:
                upgrade_hint = (f"按时还款 1 次可升至"
                                f"{min(self.LOAN_LIMIT_UPGRADE_1, self.LOAN_MAX_LIMIT)}积分")
            loan = await self._get_active_loan(session, user_id)
            if not loan:
                return True, (
                    "📭 您当前没有未还的贷款\n"
                    f"贷款余额：{loan_bal}积分（不可转账）\n"
                    f"当前信用额度：{credit_limit}积分\n"
                    f"信用分：{score}｜已按时还款 {on_time} 次\n"
                    f"💡 {upgrade_hint}"
                ), None
            _, _, principal, _, _, paid, _, _, status, start_ts, due_ts = loan
            current_interest, days_used = self._calc_loan_interest(
                int(principal), float(start_ts))
            total_now = int(principal) + current_interest
            remaining = max(0, total_now - int(paid))
            days_left = int((float(due_ts) - time.time()) // 86400)
            status_map = {"active": "正常", "overdue": "逾期"}
            msg = (
                "🏦 贷款信息\n"
                f"状态：{status_map.get(status, '未知')}\n"
                f"贷款金额：{principal}积分\n"
                f"已还：{paid}积分\n"
                f"已计息天数：{days_used}天\n"
                f"当前利息：{current_interest}积分\n"
                f"剩余应还：{remaining}积分\n"
                f"剩余天数：{max(0, days_left)}天\n"
                f"贷款余额：{loan_bal}积分（不可转账）\n"
                f"信用分：{score}｜已按时还款 {on_time} 次\n"
                f"当前信用额度：{credit_limit}积分\n"
                f"💡 {upgrade_hint}"
            )
            if status == "overdue":
                msg += "\n⚠️ 已逾期！所有收入将自动用于还款"
            return True, msg, None

        _, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    async def _check_overdue_loans(self):
        """每日凌晨 0 点：标记逾期贷款、自动从普通余额扣款还贷、私聊通知用户。

        逾期后利息继续按日累计；开启自动扣款时每天把逾期用户普通余额中
        能扣的部分扣走还贷，直到本息还清为止。
        """
        if not self.feature_flags.get("enable_loan", True):
            return
        now_ts = time.time()

        async def fn(session):
            rows = (await session.execute(text(
                "SELECT l.id, l.user_id, l.amount, l.paid, l.start_date, u.balance "
                "FROM loans l LEFT JOIN users u ON u.user_id=l.user_id "
                "WHERE (l.status='active' AND l.due_date < :t) OR "
                "(l.status='overdue' AND l.paid < l.amount + l.interest)"
            ), {"t": now_ts})).all()
            count = 0
            for loan_id, uid, principal, paid, start_ts, balance in rows:
                uid = str(uid)
                current_interest, _ = self._calc_loan_interest(
                    int(principal), float(start_ts), now_ts)
                total_now = int(principal) + current_interest
                remaining = max(0, total_now - int(paid))
                was_active = (await session.execute(text(
                    "SELECT status FROM loans WHERE id=:i"
                ), {"i": loan_id})).first()[0] == "active"
                await session.execute(text(
                    "UPDATE loans SET status='overdue', interest=:i2, total_due=:t2 "
                    "WHERE id=:i AND status='active'"
                ), {"i2": current_interest, "t2": total_now, "i": loan_id})
                balance = int(balance or 0)
                # 自动扣款：从普通余额扣走能扣的部分（贷款余额不可用于还款之外的自动扣）
                auto_text = ""
                if self.LOAN_AUTO_REPAY_ENABLED and balance > 0 and remaining > 0:
                    deduct = min(balance, remaining)
                    new_paid = int(paid) + deduct
                    await session.execute(text(
                        "UPDATE users SET balance=balance-:d, "
                        "total_spent=total_spent+:d WHERE user_id=:u"
                    ), {"d": deduct, "u": uid})
                    await session.execute(text(
                        "UPDATE loans SET paid=:p WHERE id=:i"
                    ), {"p": new_paid, "i": loan_id})
                    await session.execute(text(
                        "INSERT INTO point_transactions("
                        "user_id, amount, operation, earned, spent, balance_after, create_time) "
                        "VALUES(:u, :a, 'loan_auto_repay', 0, :s, :b, :t)"
                    ), {"u": uid, "a": -deduct, "s": deduct,
                        "b": balance - deduct, "t": time.time()})
                    remaining -= deduct
                    if remaining <= 0:
                        # 逾期还清：信用分惩罚、按时次数归零、额度自动重置
                        await session.execute(text(
                            "UPDATE loans SET status='paid', closed_date=:c WHERE id=:i"
                        ), {"c": time.time(), "i": loan_id})
                        await self._loan_settle_credit(session, uid, overdue=True)
                        self._pending_loan_notifies.append(
                            (uid, "✅ 逾期贷款已全部还清！"
                             f"信用分 {self.LOAN_CREDIT_PENALTY}，"
                             f"额度已重置为 {self.LOAN_INITIAL_LIMIT} 积分"))
                        count += 1
                        continue
                    auto_text = (f"已自动从余额扣除 {deduct} 积分用于还款，"
                                 f"剩余应还：{remaining} 积分")
                else:
                    auto_text = f"剩余应还：{remaining} 积分"
                if was_active:
                    self._pending_loan_notifies.append(
                        (uid, f"⚠️ 贷款已逾期！{auto_text}\n"
                         "利息继续按日计算，收入将在每日结算时自动用于还款"))
                count += 1
            return True, "ok", count

        await self._tx(fn)

    # ============================================================
    #  功能七：群活跃奖励
    # ============================================================
    async def _load_activity_counts(self):
        """启动时从数据库恢复今日发言统计，避免插件更新后活跃计数清零。"""
        today = datetime.now(TZ).date().isoformat()
        try:
            async with self._session() as session:
                rows = (await session.execute(text(
                    "SELECT group_key, user_id, user_name, count FROM activity_stats "
                    "WHERE date=:d"
                ), {"d": today})).all()
            for gk, uid, name, cnt in rows:
                bucket = self._activity_counts.setdefault(
                    str(gk), {"date": today, "users": {}}
                )
                bucket["users"][str(uid)] = {
                    "name": str(name or uid), "count": int(cnt or 0)
                }
            if rows:
                self.logger.info(f"已恢复 {len(rows)} 条今日群活跃统计")
        except Exception:
            self.logger.exception("恢复群活跃统计失败")

    async def _persist_activity(self, key: str, today: str, user_id: str, user_name: str):
        """把一次发言计数落库（失败不影响消息处理）。"""
        try:
            async with self._session() as session:
                async with session.begin():
                    await session.execute(text(
                        "INSERT INTO activity_stats(group_key, date, user_id, user_name, count) "
                        "VALUES(:k, :d, :u, :n, 1) "
                        "ON CONFLICT(group_key, date, user_id) DO UPDATE SET "
                        "count=activity_stats.count+1, user_name=:n"
                    ), {"k": key, "d": today, "u": user_id, "n": user_name})
        except Exception:
            self.logger.exception("群活跃统计落库失败")

    @filter.event_message_type(EventMessageType.GROUP_MESSAGE)
    async def count_group_activity(self, event: AstrMessageEvent):
        """统计群聊发言，系统消息也按一条消息计数。"""
        group_id = str(event.get_group_id() or "").strip()
        user_id = str(event.get_sender_id() or "").strip()
        if not group_id or not user_id or user_id == str(event.get_self_id() or ""):
            return
        today = datetime.now(TZ).date().isoformat()
        key = f"{event.get_platform_id()}:{group_id}"
        user_name = str(event.get_sender_name() or user_id).strip()
        async with self._activity_lock:
            bucket = self._activity_counts.setdefault(key, {"date": today, "users": {}})
            if bucket["date"] != today:
                bucket["date"] = today
                bucket["users"] = {}
            entry = bucket["users"].setdefault(user_id, {"name": user_name, "count": 0})
            entry["name"] = user_name or entry["name"]
            entry["count"] += 1
        # 写透到数据库，插件重启/更新后可恢复
        await self._persist_activity(key, today, user_id, user_name)

    async def _settle_activity_rewards(self):
        """每天22:00按群结算发言前三名并清空统计。"""
        if not self.feature_flags.get("enable_activity", True):
            return  # 配置页关闭群活跃奖励，跳过结算
        today = datetime.now(TZ).date().isoformat()
        # 顺手清理过期日期的统计
        try:
            async with self._session() as session:
                async with session.begin():
                    await session.execute(text(
                        "DELETE FROM activity_stats WHERE date < :d"
                    ), {"d": today})
        except Exception:
            self.logger.exception("清理过期群活跃统计失败")
        async with self._activity_lock:
            snapshots = [(key, bucket) for key, bucket in self._activity_counts.items()
                         if bucket.get("date") == today and bucket.get("users")]
        for key, bucket in snapshots:
            platform_id, group_id = key.split(":", 1)
            ranking = sorted(bucket["users"].items(), key=lambda item: item[1]["count"], reverse=True)[:3]
            rewards = (50, 30, 10)

            async def fn(session):
                chain = [Plain("🔥 群活跃奖励结算")]
                for rank, ((user_id, info), reward) in enumerate(zip(ranking, rewards), 1):
                    await self._ensure_user(session, user_id, info["name"])
                    await self._add_points(session, user_id, reward, "群活跃第%d名" % rank)
                    chain.extend([
                        Plain(f"\n第{rank}名 "),
                        At(qq=str(user_id)),
                        Plain(f" {info['name']}：{info['count']} 条，+{reward} 积分"),
                    ])
                return True, "ok", chain

            ok, _, chain = await self._tx(fn)
            if ok and chain:
                await self._send_group_chain(platform_id, group_id, chain)
                async with self._activity_lock:
                    current = self._activity_counts.get(key)
                    if current is bucket:
                        current["users"] = {}
                # 同步清理数据库里该群今日统计
                try:
                    async with self._session() as session:
                        async with session.begin():
                            await session.execute(text(
                                "DELETE FROM activity_stats WHERE group_key=:k AND date=:d"
                            ), {"k": key, "d": today})
                except Exception:
                    self.logger.exception("清理群活跃统计失败")

    # ============================================================
    #  功能八：管理指令 / 签到 / 排行
    # ============================================================
    async def _grant_points(self, event: AstrMessageEvent, negative: bool):
        """/加积分|减积分 @用户 数量（仅配置页管理员QQ可用）"""
        sender = str(event.get_sender_id())
        if sender not in self.ADMIN_QQ:
            yield event.plain_result("仅配置的管理员可使用该指令喵~ 请在插件配置页「管理员QQ」中添加")
            return
        user_id = self._extract_at(event)
        cmd = "减积分" if negative else "加积分"
        command_names = [f"积分 {cmd}", cmd]
        if negative:
            command_names.insert(1, "积分 扣积分")
            command_names.append("扣积分")
        args = ""
        for command_name in command_names:
            args = self._strip_command(event, command_name)
            if args:
                break
        parts = args.split()
        amount = None
        # 目标 QQ 也可能是纯数字，因此数量取最后一个数字参数。
        for p in reversed(parts):
            if p.isdigit():
                amount = int(p)
                break
        if not user_id:
            yield event.plain_result(f"用法：/{cmd} @用户 数量 喵~")
            return
        if amount is None or amount <= 0:
            yield event.plain_result("数量需要是正整数喵~")
            return
        delta = -amount if negative else amount
        target = user_id

        async def fn(session):
            await self._ensure_user(session, target)
            await self._add_points(session, target, delta, "管理员加分" if delta > 0 else "管理员扣分")
            new_bal = await self._balance(session, target)
            return True, f"✅ 已给 {target} {'加上' if delta > 0 else '扣除'} {abs(delta)} 积分，当前积分：{new_bal} 喵~", None

        ok, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    @filter.command("加积分")
    async def grant_add(self, event: AstrMessageEvent):
        async for result in self._grant_points(event, negative=False):
            yield result

    # ============================================================
    #  管理指令：银行管理（仅管理员）
    # ============================================================
    async def _bank_admin(self, event: AstrMessageEvent, action: str):
        """管理员管理指定玩家的银行账户：查看/加款/扣款/清空。"""
        sender = str(event.get_sender_id())
        if sender not in self.ADMIN_QQ:
            yield event.plain_result("仅配置的管理员可使用该指令喵~ 请在插件配置页「管理员QQ」中添加")
            return
        target = self._extract_at(event)
        if not target:
            if action == "info":
                yield event.plain_result("用法：/银行信息 @玩家 喵~")
            else:
                yield event.plain_result(f"用法：/银行{action} @玩家 积分 喵~")
            return
        args = self._strip_command(event, f"银行{action}").split()
        amount = None
        if action in ("加款", "扣款"):
            nums = [a for a in args if a.isdigit()]
            amount = int(nums[0]) if nums else None
            if amount is None or amount <= 0:
                yield event.plain_result(f"❌ 请输入有效金额，如：/银行{action} @玩家 100")
                return

        async def fn(session):
            row = (await session.execute(text(
                "SELECT user_name FROM users WHERE user_id=:u"
            ), {"u": target})).first()
            if not row:
                raise _BizError("这个玩家还没有积分数据喵~")
            name = str(row[0]).strip() or target
            bank = (await session.execute(text(
                "SELECT current_balance, total_interest, created_at FROM bank_accounts "
                "WHERE user_id=:u"
            ), {"u": target})).first()
            if action == "info":
                if not bank:
                    return True, (f"🏦 玩家 {name} 还没有开通银行账户喵~"), None
                estimate = int(int(bank[0]) * self.CURRENT_INTEREST_RATE)
                return True, (
                    f"🏦 玩家 {name} 的银行账户\n"
                    f"💳 活期余额：{bank[0]}积分\n"
                    f"📈 预计每日收益：{estimate}积分\n"
                    f"💰 累计利息：{bank[1]}积分"
                ), None
            if not bank:
                raise _BizError(f"玩家 {name} 还没有开通银行账户，无法{action}喵~")
            cur = int(bank[0])
            if action == "加款":
                new_bal = cur + amount
                await session.execute(text(
                    "UPDATE bank_accounts SET current_balance=:b WHERE user_id=:u"
                ), {"b": new_bal, "u": target})
                # 银行流水：管理员加款（不进存款/取款统计，避免重复计入）
                await session.execute(text(
                    "INSERT INTO bank_transactions(user_id, type, amount, create_time) "
                    "VALUES(:u, 'admin_add', :a, :t)"
                ), {"u": target, "a": amount, "t": time.time()})
                return True, (
                    f"✅ 已为玩家 {name} 的银行账户加款 {amount} 积分\n"
                    f"当前活期余额：{new_bal}积分"
                ), None
            if action == "扣款":
                deduct = min(cur, amount)
                new_bal = cur - deduct
                await session.execute(text(
                    "UPDATE bank_accounts SET current_balance=:b WHERE user_id=:u"
                ), {"b": new_bal, "u": target})
                await session.execute(text(
                    "INSERT INTO bank_transactions(user_id, type, amount, create_time) "
                    "VALUES(:u, 'admin_deduct', :a, :t)"
                ), {"u": target, "a": deduct, "t": time.time()})
                note = f"（账户余额不足，实际扣除 {deduct} 积分）" if deduct < amount else ""
                return True, (
                    f"✅ 已从玩家 {name} 的银行账户扣除 {deduct} 积分{note}\n"
                    f"当前活期余额：{new_bal}积分"
                ), None
            # 清空
            await session.execute(text(
                "UPDATE bank_accounts SET current_balance=0 WHERE user_id=:u"
            ), {"u": target})
            await session.execute(text(
                "INSERT INTO bank_transactions(user_id, type, amount, create_time) "
                "VALUES(:u, 'admin_deduct', :a, :t)"
            ), {"u": target, "a": cur, "t": time.time()})
            return True, (
                f"✅ 已清空玩家 {name} 的银行账户\n"
                f"清除活期余额：{cur}积分"
            ), None

        ok, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    @filter.command("银行信息")
    async def bank_admin_info(self, event: AstrMessageEvent):
        """/银行信息 @玩家 —— 管理员查看指定玩家的银行账户"""
        async for result in self._bank_admin(event, "info"):
            yield result

