    async def _web_group_toggle(self):
        from astrbot.api.web import json_response, error_response, request as web_request
        if not self._web_admin_ok():
            return error_response("无权限：当前面板用户不在管理名单中", 403)
        try:
            req = web_request
            body = await req.json()
            group_id = str(body.get("group_id", "")).strip()
            enabled = 1 if body.get("enabled") else 0
            platform_id = str(body.get("platform_id", "")).strip()
        except Exception as e:
            return error_response(f"参数错误：{e}")
        if not group_id:
            return error_response("缺少 group_id")

        async def fn(session):
            await session.execute(
                text(
                    "INSERT INTO group_settings(group_id, enabled, updated_at, platform_id) VALUES(:g, :e, :t, :p) "
                    "ON CONFLICT(group_id) DO UPDATE SET enabled=:e, updated_at=:t, platform_id=:p"
                ),
                {"g": group_id, "e": enabled, "t": time.time(), "p": platform_id},
            )
            return True, "ok", None

        ok, msg, _ = await self._tx(fn)
        return json_response({"ok": ok, "message": msg})

    async def _web_mode_set(self):
        from astrbot.api.web import json_response, error_response, request as web_request
        if not self._web_admin_ok():
            return error_response("无权限：当前面板用户不在管理名单中", 403)
        try:
            req = web_request
            body = await req.json()
            mode = str(body.get("mode", "")).strip()
        except Exception as e:
            return error_response(f"参数错误：{e}")
        if mode not in ("whitelist", "blacklist"):
            return error_response("mode 只能是 whitelist 或 blacklist")

        async def fn(session):
            await self._set_config_value(session, "group_mode", mode)
            return True, "ok", None

        ok, msg, _ = await self._tx(fn)
        return json_response({"ok": ok, "message": msg})

    async def _web_grant(self):
        from astrbot.api.web import json_response, error_response, request as web_request
        if not self._web_admin_ok():
            return error_response("无权限：当前面板用户不在管理名单中", 403)
        try:
            req = web_request
            body = await req.json()
            user_id = str(body.get("user_id", "")).strip()
            amount = int(body.get("amount", 0))
        except Exception as e:
            return error_response(f"参数错误：{e}")
        if not user_id:
            return error_response("缺少 user_id")
        if amount == 0:
            return error_response("amount 不能为 0")

        async def fn(session):
            await self._ensure_user(session, user_id)
            await self._add_points(session, user_id, amount, "管理员加分" if amount > 0 else "管理员扣分")
            new_bal = await self._balance(session, user_id)
            return True, f"ok", {"user_id": user_id, "balance": new_bal}

        ok, msg, data = await self._tx(fn)
        if not ok:
            return error_response(msg)
        return json_response(data)

    # ============================================================
    #  钓鱼系统
    # ============================================================
    def _fishing_roll_event(self) -> str:
        """按 FISHING_EVENTS 概率表随机判定一次挂机事件"""
        roll = random.uniform(0, 100)
        cumulative = 0.0
        for name, prob in FISHING_EVENTS:
            cumulative += prob
            if roll <= cumulative:
                return name
        return "空钩"

    def _fishing_pick_fish(self):
        """按概率加权随机抽一条鱼，返回 (鱼名, 售价, 稀有度, 单条概率%)。"""
        roll = random.uniform(0, 100)
        cumulative = 0.0
        for name, (price, rarity, prob) in FISH_POOL.items():
            cumulative += prob
            if roll <= cumulative:
                return name, price, rarity, prob
        return None  # 杂物：水面漂过一片水草，一无所得

    def _fishing_apply_pond_upgrade(self, picked):
        """在每条渔获判定时应用鱼塘加成，返回 (渔获, 是否由鱼塘升级)。

        放在 _fishing_check 的逐条渔获路径调用，普通上钩和鱼汛普通保底都会生效，
        同时让播报能明确展示「鱼塘加成升级」。
        """
        if picked is None:
            return None, False
        name, price, rarity, prob = picked
        bonus = int(getattr(self, "_pond_rare_bonus", 0) or 0)
        if rarity == "普通" and bonus > 0 and random.random() < (bonus / 100.0):
            return self._fishing_pick_fish_tier("稀有"), True
        return picked, False

    def _fishing_pick_fish_tier(self, tier: str):
        """从指定稀有度档位随机抽一条鱼（保底必出，不含杂物）"""
        prob_total, fishes = FISH_TABLE.get(tier, FISH_TABLE["普通"])
        name, price = random.choice(fishes)
        return name, price, tier, prob_total / len(fishes)

    async def _fishing_ensure_stats(self, session, user_id: str) -> None:
        """确保钓鱼统计行存在，并惰性重置过期计数（必须在事务内调用）"""
        today = date.today().isoformat()
        row = (await session.execute(
            text("SELECT today_date FROM fishing_stats WHERE user_id=:u"), {"u": user_id}
        )).first()
        if not row:
            await session.execute(
                text("INSERT INTO fishing_stats(user_id, today_date, pond_level) VALUES(:u, :d, 1)"),
                {"u": user_id, "d": today},
            )
        elif row[0] != today:
            await session.execute(
                text("UPDATE fishing_stats SET today_count=0, today_date=:d WHERE user_id=:u"),
                {"u": user_id, "d": today},
            )

    async def _fishing_bait_count(self, session, user_id: str) -> int:
        """查询当前鱼饵数量（必须在事务内调用）"""
        row = (await session.execute(
            text("SELECT count FROM fishing_baits WHERE user_id=:u"), {"u": user_id}
        )).first()
        return int(row[0] or 0) if row else 0

    async def _get_broadcast_groups(self) -> list[tuple[str, str]]:
        """获取已开启玩法的群列表（group_settings 优先，platform_manager 全平台兜底）"""
        try:
            async with self._session() as session:
                rows = (await session.execute(text(
                    "SELECT group_id, platform_id FROM group_settings WHERE enabled=1"
                ))).all()
            groups = [(str(p or ""), str(g)) for g, p in rows]
            if not groups:
                self.logger.warning("没有已开启玩法的群（group_settings 为空），无法兜底播报")
            return groups
        except Exception:
            self.logger.exception("获取播报群列表失败")
            return []

    async def _get_platform_ids(self) -> list[str]:
        """获取当前所有平台实例 ID（AstrBot 兼容写法）"""
        ids: list[str] = []
        try:
            manager = getattr(self.context, "platform_manager", None)
            if manager and hasattr(manager, "get_insts"):
                ids = [str(p.meta().id) for p in manager.get_insts() if p.meta().id]
            elif manager and hasattr(manager, "platform_insts"):
                ids = [str(p.meta().id) for p in manager.platform_insts if p.meta().id]
        except Exception:
            pass
        return ids

    async def _send_with_fallback(
        self, platform_id: str, group_id: str, chain: list, tag: str,
        cross_group_fallback: bool = True,
    ) -> bool:
        """多重路径发送播报。

        配置了 fishing_broadcast_groups 时只发配置的群（所有平台实例都试）；
        否则按「竿里存的平台ID → 当前所有平台实例」重试；
        cross_group_fallback=True 时最后还会尝试所有已开启玩法的群（跨群兜底）。

        聚合播报图必须传 cross_group_fallback=False：目标群发送失败时宁可丢弃，
        也不能把 A 群的播报漏发到 B 群（否则 B 群一周期收到两张播报图）。
        """
        targets: list[tuple[str, str]] = []
        if self.FISHING_BROADCAST_GROUPS:
            # 配置了播报群：定向发送到配置的群
            pids = await self._get_platform_ids() or [str(platform_id or "")]
            for group in self.FISHING_BROADCAST_GROUPS:
                for pid in pids:
                    targets.append((pid, group))
            for t_platform, t_group in targets:
                try:
                    await self._send_group_chain(t_platform, t_group, chain)
                except Exception:
                    self.logger.exception(
                        f"{tag}发送到播报群失败（{t_platform}:{t_group}）"
                    )
            return True
        if group_id:
            targets.append((str(platform_id), str(group_id)))
            for pid in await self._get_platform_ids():
                if pid and (pid, str(group_id)) not in targets:
                    targets.append((pid, str(group_id)))
        if cross_group_fallback:
            for fb_platform, fb_group in await self._get_broadcast_groups():
                if (fb_platform, fb_group) not in targets:
                    targets.append((fb_platform, fb_group))
        for t_platform, t_group in targets:
            try:
                await self._send_group_chain(t_platform, t_group, chain)
                if (t_platform, t_group) != (str(platform_id), str(group_id)):
                    self.logger.info(f"{tag}已通过兜底路径送达（{t_platform}:{t_group}）")
                return True
            except Exception:
                self.logger.exception(f"{tag}发送失败（{t_platform}:{t_group}）")
        self.logger.warning(f"{tag}所有发送路径均失败（群号：{group_id or '空'}）")
        return False

    # ============================================================
    #  指令入口：系统钱包
    # ============================================================
    @filter.command("系统")
    async def system_wallet_command(self, event: AstrMessageEvent):
        """/系统 —— 查看系统钱包；管理员可 存/取/流水"""
        gate_ok, gate_msg = await self._check_group_gate(event, "系统")
        if not gate_ok:
            yield event.plain_result(gate_msg)
            return
        sender = str(event.get_sender_id()).strip()
        parts = self._strip_command(event, "系统").split()
        subcmd = parts[0] if parts else ""

        # ---- 无参数：所有人可查余额概况 ----
        if not subcmd:
            async def fn(session):
                bal, t_in, t_out = await self._wallet_ensure(session)
                return True, "ok", (bal, t_in, t_out)
            ok, _, data = await self._tx(fn)
            if not ok or data is None:
                yield event.plain_result("数据库开小差了喵~ 稍后再试")
                return
            bal, t_in, t_out = data
            yield event.plain_result(
                "🏦 【系统钱包】\n"
                f"💰 当前余额：{bal} 积分\n"
                f"📈 累计流入：{t_in} 积分\n"
                f"📉 累计流出：{t_out} 积分"
            )
            return

        # ---- 以下子命令仅管理员可用 ----
        if sender not in self.ADMIN_QQ:
            yield event.plain_result("❌ 仅管理员可操作")
            return

        if subcmd in ("存", "取"):
            if len(parts) < 2:
                yield event.plain_result(f"❌ 格式：/系统 {subcmd} [积分]")
                return
            try:
                amount = int(parts[1])
            except ValueError:
                yield event.plain_result("❌ 积分必须是整数喵~")
                return
            if amount < 1:
                yield event.plain_result("❌ 积分必须大于 0")
                return

            if subcmd == "存":
                async def fn(session):
                    # 只扣普通余额（贷款余额不可充值资金池，防止套现）
                    await self._ensure_user(session, sender)
                    row = (await session.execute(text(
                        "SELECT balance FROM users WHERE user_id=:u"
                    ), {"u": sender})).first()
                    bal = int(row[0]) if row else 0
                    if bal < amount:
                        raise _BizError(
                            f"❌ 你的余额不足！当前余额：{bal} 积分"
                        )
                    await self._add_points(
                        session, sender, -amount, "admin_wallet_deposit",
                        earned=0, spent=amount, force_normal=True,
                    )
                    await self._wallet_inflow_s(
                        session, amount, "admin_deposit",
                        f"管理员 {sender} 存入"
                    )
                    new_bal = await self._wallet_ensure(session)
                    return True, "ok", new_bal[0]
                ok, msg, data = await self._tx(fn)
                yield event.plain_result(
                    f"✅ 已存入系统钱包 {amount} 积分！\n"
                    f"当前系统钱包余额：{data}"
                    if ok else msg
                )
                return

            # 取
            async def fn(session):
                if not await self._wallet_outflow_s(
                    session, amount, "admin_withdraw",
                    f"管理员 {sender} 取出"
                ):
                    raise _BizError(
                        "❌ 系统钱包余额不足！当前余额："
                        f"{await self._wallet_balance_q(session)}"
                    )
                await self._add_points(
                    session, sender, amount, "admin_wallet_withdraw",
                    earned=amount, spent=0,
                )
                new_bal = await self._wallet_ensure(session)
                return True, "ok", new_bal[0]
            ok, msg, data = await self._tx(fn)
            yield event.plain_result(
                f"✅ 已取出 {amount} 积分到你的余额！\n"
                f"当前系统钱包余额：{data}"
                if ok else msg
            )
            return

        if subcmd == "流水":
            try:
                page = int(parts[1]) if len(parts) > 1 else 1
            except ValueError:
                page = 1
            page = max(1, page)
            size = self.WALLET_LOG_PAGE_SIZE

            async def fn(session):
                total = int((await session.execute(text(
                    "SELECT COUNT(*) FROM system_wallet_log"
                ))).first()[0])
                rows = (await session.execute(text(
                    "SELECT type, amount, source, remark, create_time "
                    "FROM system_wallet_log ORDER BY id DESC LIMIT :n OFFSET :o"
                ), {"n": size, "o": (page - 1) * size})).all()
                return True, "ok", (total, rows)
            ok, _, data = await self._tx(fn)
            if not ok or data is None:
                yield event.plain_result("数据库开小差了喵~ 稍后再试")
                return
            total, rows = data
            if not rows:
                yield event.plain_result("📭 该页没有流水记录喵~")
                return
            total_pages = max(1, (total + size - 1) // size)
            lines = [f"📒 系统钱包流水（第 {page}/{total_pages} 页，共 {total} 条）"]
            for rtype, ramount, rsource, rremark, rtime in rows:
                arrow = "↑" if rtype == "inflow" else "↓"
                try:
                    time_txt = datetime.fromtimestamp(float(rtime), TZ).strftime("%m-%d %H:%M")
                except (TypeError, ValueError):
                    time_txt = str(rtime)[:16]
                lines.append(
                    f"{arrow} {'+' if rtype == 'inflow' else '-'}{ramount} "
                    f"[{rsource}] {rremark or ''} {time_txt}"
                )
            yield event.plain_result("\n".join(lines))
            return

        yield event.plain_result("❌ 可用子命令：存、取、流水（无参数=查看余额）")

    async def _wallet_balance_q(self, session) -> int:
        """事务内快捷读取钱包余额（不建行）。"""
        row = (await session.execute(text(
            "SELECT balance FROM system_wallet LIMIT 1"
        ))).first()
        return int(row[0]) if row else 0

    async def _fishing_check(self):
        """定时任务：每 30 分钟判定一次所有挂机中的鱼竿。

        每根竿消耗 1 个鱼饵后随机判定事件：
        上钩的鱼先进 fishing_pending，等玩家 /收鱼 进鱼篓；
        高价值鱼 / 至高传说直接全群广播（真实 At 组件）。

        休息时间：北京时间 0:00-7:00 不进行判定（鱼儿也要休息喵~）
        """
        # 0点到7点为休息时间，不判定
        bj_hour = datetime.now(self._beijing_tz).hour
        if 0 <= bj_hour < 7:
            return

        async def fn(session):
            rods = (await session.execute(text(
                "SELECT r.id, r.user_id, r.slot, r.platform_id, r.group_id, "
                "COALESCE(NULLIF(u.user_name, ''), r.user_id) "
                "FROM fishing_rods r LEFT JOIN users u ON u.user_id = r.user_id "
                "WHERE r.status='fishing'"
            ))).all()
            if not rods:
                return False, "没有挂机中的鱼竿", None
            fishing_count = len(rods)  # 鱼群效应：当前全服挂机竿数
            broadcasts: list[tuple[str, str, list]] = []   # (platform_id, group_id, 消息链)
            notices: list[tuple[str, str, str]] = []       # (platform_id, group_id, 事件播报文本)
            # 今日天气（全服统一，惰性生成，影响本判定所有鱼竿）
            weather_key, weather_cfg = await self._weather_today(session)
            for rod in rods:
                rid, uid, slot, platform_id, group_id, user_name = rod
                group_id = str(group_id or "")

                def notify(text_line: str):
                    """本群事件播报（不艾特，只说谁遇到了什么事）"""
                    if group_id:
                        notices.append((platform_id, group_id, f"🎣 {user_name} {text_line}"))
                await self._fishing_ensure_stats(session, uid)
                # 鱼塘等级（每判定读取一次，应用到本判定的鱼饵与稀有加成）
                pond_row = (await session.execute(text(
                    "SELECT pond_level FROM fishing_stats WHERE user_id=:u"
                ), {"u": uid})).first()
                pond_level = int(pond_row[0] or 1) if pond_row else 1
                pond_rare_bonus = self.POND_RARE_BONUS.get(pond_level, 0)
                # 商店加成：幸运符生效中+5稀有；高级竿生效中本判定多捕1条(见渔获)；双倍/VIP在卖鱼生效
                fish_shop = await self._get_shop_items(session, uid)
                if self._shop_active(fish_shop, "charm"):
                    pond_rare_bonus = pond_rare_bonus + 5  # 幸运护身符生效中
                self._pond_rare_bonus = pond_rare_bonus   # 供本次判定抽鱼使用
                self._active_shop = fish_shop              # 供本判定后续阶段读取
                # 判定前消耗 1 个鱼饵，没鱼饵自动收杆
                bait = await self._fishing_bait_count(session, uid)
                if bait <= 0:
                    await session.execute(
                        text("UPDATE fishing_rods SET status='idle' WHERE id=:i"), {"i": rid}
                    )
                    notify("的鱼饵用完了，自动收杆休息啦~")
                    continue
                await session.execute(
                    text("UPDATE fishing_baits SET count=count-1 WHERE user_id=:u"), {"u": uid}
                )
                # 鱼塘减耗效果：按减耗百分比有几率回补鱼饵（折扣卡生效中额外+20%省饵）
                pond_bait_pct = self.POND_BAIT_REDUCTION.get(pond_level, 0)
                if self._shop_active(self._active_shop or {}, "discount"):
                    pond_bait_pct = pond_bait_pct + 20  # 鱼饵折扣卡生效中
                if pond_bait_pct > 0 and random.random() < (min(pond_bait_pct, 95) / 100.0):
                    await session.execute(
                        text("UPDATE fishing_baits SET count=count+1 WHERE user_id=:u"),
                        {"u": uid},
                    )
                # 幸运日 buff：有效期内空钩视为上钩
                st = (await session.execute(
                    text("SELECT lucky_day_expire FROM fishing_stats WHERE user_id=:u"),
                    {"u": uid},
                )).first()
                lucky_active = bool(st and st[0] and float(st[0]) > time.time())
                event = self._fishing_roll_event()
                if event == "空钩" and lucky_active:
                    event = "正常上钩"
                # 本次判定统计（每次判定消耗 1 鱼饵）
                await session.execute(text(
                    "UPDATE fishing_stats SET total_baits_used=total_baits_used+1, "
                    "today_count=today_count+1 WHERE user_id=:u"
                ), {"u": uid})
                # 鱼群效应：挂机竿越多越有收获（概率=竿数×7%，+1积分）
                if random.randint(1, 100) <= min(100, fishing_count * 7):
                    await self._add_points(session, uid, 1, "鱼群效应")
                multi_map = {
                    "正常上钩": (1, None), "双鱼上钩": (2, None), "鱼群爆发": (3, None),
                    "黄金鱼群": (2, None), "鱼汛大潮": (3, "普通"), "河水涨潮": (2, "普通"),
                    "传说召唤阵": (1, "传说"),
                }
                # 暴风雨：上钩类事件 30% 概率化为空钩（钓鱼成功率-30%）
                if weather_cfg.get("fail_pct") and event in multi_map and \
                        random.random() < weather_cfg["fail_pct"] / 100.0:
                    event = "空钩"
                    notify("暴风雨太猛了，到手的鱼脱钩跑掉了…")
                if event in multi_map:
                    # 上钩：鱼先进入 pending，等 /收鱼（指定档位保底必出，普通档可能钓上杂物）
                    caught, force_tier = multi_map[event]
                    if self._shop_active(self._active_shop or {}, "advanced"):
                        caught = caught + 1  # 高级鱼竿生效中：额外多捕1条
                    fish_names: list[str] = []
                    junk = 0
                    for _ in range(caught):
                        raw_picked = self._fishing_pick_fish_tier(force_tier) if force_tier else self._fishing_pick_fish()
                        # 鱼塘转化明确在每条渔获的判定路径执行，方便播报和排查
                        picked, pond_upgraded = self._fishing_apply_pond_upgrade(raw_picked)
                        if picked is None:
                            junk += 1
                            continue  # 杂物
                        name, price, rarity, prob = picked
                        upgrade_tag = "·鱼塘加成↑" if pond_upgraded else ""
                        # 天气加成：雨天/寒冷/雾天把普通鱼升级为稀有/珍稀/传说
                        wtier = weather_cfg.get("tier")
                        if wtier and rarity == "普通" and \
                                random.random() < weather_cfg["pct"] / 100.0:
                            name, price, rarity, prob = self._fishing_pick_fish_tier(wtier)
                            upgrade_tag = f"{upgrade_tag}·天气加成↑" if upgrade_tag else "·天气加成↑"
                        # 天气大型鱼/满月价值乘数（随渔获保留到卖出）
                        bigfish = bool(weather_cfg.get("bigfish")) and \
                            random.random() < weather_cfg["bigfish"] / 100.0
                        value_mult = self._weather_value_mult(weather_cfg, bigfish)
                        if bigfish:
                            upgrade_tag = f"{upgrade_tag}·🐋大鱼" if upgrade_tag else "·🐋大鱼"
                        # 闪光判定：1% 概率为闪光版，售价 ×3（pending 以 ✨闪光 前缀名携带闪光标记）
                        if random.random() < self.FISHING_SHINY_RATE:
                            name = f"{self.FISHING_SHINY_PREFIX}{name}"
                            price = int(price * self.FISHING_SHINY_MULT)
                            upgrade_tag = f"{upgrade_tag}·闪光×3" if upgrade_tag else "·闪光×3"
                        fish_names.append(f"{name}（{price}积分{upgrade_tag}）")
                        await session.execute(text(
                            "INSERT INTO fishing_pending(user_id, fish_name, value_mult, catch_time) "
                            "VALUES(:u, :n, :m, :t)"
                        ), {"u": uid, "n": name, "m": value_mult, "t": time.time()})
                        await session.execute(text(
                            "UPDATE fishing_stats SET total_caught=total_caught+1 WHERE user_id=:u"
                        ), {"u": uid})
                        # 更新每日钓鱼任务
                        await self._fishing_task_tick(session, uid, 1, name, price)
                        # 全群广播：传说级及以上（售价 > 1000 也触发）
                        if rarity in self.FISHING_BROADCAST_RARITIES or price > self.FISHING_BROADCAST_PRICE:
                            chain = [At(qq=str(uid))]
                            if rarity == "至高传说":
                                chain.append(Plain(
                                    f" 🌟🌟🌟 钓到了传说中的 {name}（价值{price}积分！概率{f'{prob:.6f}'.rstrip('0').rstrip('.')}%！！！）\n"
                                    f"此乃万中无一之奇迹！"
                                ))
                            else:
                                chain.append(Plain(
                                    f" 🎉🎉🎉 钓到了 {name}（价值{price}积分！概率{f'{prob:.6f}'.rstrip('0').rstrip('.')}%！！！）"
                                ))
                            if group_id:
                                broadcasts.append((platform_id, group_id, chain))
                    if junk and not fish_names:
                        notify("感觉有东西咬钩，拉上来一只破靴子，一无所得…")
                    elif fish_names:
                        prefix = "一次钓上两条！" if caught == 2 and fish_names else ""
                        notify(f"{prefix}有鱼上钩啦，{('、'.join(fish_names))} 进了鱼篓！")
                        await self._fishing_task_streak(session, uid, broke=False)
                elif event == "神秘宝箱":
                    amount = random.randint(self.FISHING_BOX_MIN, self.FISHING_BOX_MAX)
                    await self._add_points(session, uid, amount, "钓鱼宝箱")
                    notify(f"捞到一个神秘宝箱，开出 {amount} 积分！")
                elif event == "双倍宝箱":
                    amount = random.randint(100, 200)
                    await self._add_points(session, uid, amount, "钓鱼宝箱")
                    notify(f"捞到一个双倍宝箱，开出 {amount} 积分！")
                elif event == "沉船宝藏":
                    amount = random.randint(80, 150)
                    await self._add_points(session, uid, amount, "钓鱼宝藏")
                    notify(f"发现一处沉船宝藏，获得 {amount} 积分！")
                elif event == "老渔夫传授":
                    await self._add_points(session, uid, 200, "钓鱼奇遇")
                    notify("遇到一位老渔夫传授毕生经验，获得 200 积分！")
                elif event == "渔协补贴":
                    await self._add_points(session, uid, 100, "钓鱼补贴")
                    notify("渔业协会发放挂机补贴，+100 积分！")
                elif event == "钓到旧靴子":
                    amount = random.randint(5, 20)
                    await self._add_points(session, uid, amount, "钓鱼杂货")
                    notify(f"钓到一只旧靴子，里面居然藏着 {amount} 积分！")
                elif event == "钓到漂流瓶":
                    amount = random.randint(10, 50)
                    await self._add_points(session, uid, amount, "钓鱼杂货")
                    notify(f"钓到一个漂流瓶，瓶中藏着 {amount} 积分！")
                elif event == "钓到旧轮胎":
                    await self._add_points(session, uid, 10, "钓鱼杂货")
                    notify("钓到一个旧轮胎，卖废品得了 10 积分…")
                elif event == "钓到易拉罐":
                    await self._add_points(session, uid, 5, "钓鱼杂货")
                    notify("钓到一个易拉罐，回收得 5 积分…")
                elif event == "钓到无名古币":
                    await self._add_points(session, uid, 150, "钓鱼奇遇")
                    notify("钓到一枚无名古币，收藏家出价 150 积分收购！")
                elif event == "幸运日":
                    expire = time.time() + self.FISHING_LUCKY_HOURS * 3600
                    await session.execute(text(
                        "UPDATE fishing_stats SET lucky_day=lucky_day+1, lucky_day_expire=:e "
                        "WHERE user_id=:u"
                    ), {"u": uid, "e": expire})
                    notify(f"时来运转！获得 {self.FISHING_LUCKY_HOURS} 小时幸运buff，期间必定上钩！")
                elif event == "龙王赐福":
                    expire = time.time() + 4 * 3600
                    await session.execute(text(
                        "UPDATE fishing_stats SET lucky_day=lucky_day+1, lucky_day_expire=:e "
                        "WHERE user_id=:u"
                    ), {"u": uid, "e": expire})
                    notify("龙王赐福！获得 4 小时超级幸运buff，期间必定上钩！")
                elif event == "美人鱼祝福":
                    expire = time.time() + 3 * 3600
                    await session.execute(text(
                        "UPDATE fishing_stats SET lucky_day=lucky_day+1, lucky_day_expire=:e "
                        "WHERE user_id=:u"
                    ), {"u": uid, "e": expire})
                    notify("美人鱼的祝福！获得 3 小时幸运buff，期间必定上钩！")
                elif event == "螃蟹夹饵":
                    # 额外损失最多 FISHING_CRAB_BAITS 个鱼饵
                    lost = min(self.FISHING_CRAB_BAITS, bait - 1)
                    if lost > 0:
                        await session.execute(
                            text("UPDATE fishing_baits SET count=count-:c WHERE user_id=:u"),
                            {"c": lost, "u": uid},
                        )
                        notify(f"的鱼饵被螃蟹夹走了，额外损失 {lost} 个…")
                    else:
                        notify("碰到一只螃蟹，好在没夹走鱼饵")
                elif event in ("钓具保养", "设备进水", "渔政罚款", "撞上暗礁",
                               "河豚毒素", "鲨鱼来袭", "鱼钩卷刃", "巨浪拍船",
                               "鱼群暴动", "冰雹灾害", "水蛇惊魂"):
                    fine_map = {
                        "钓具保养": self.FISHING_FINE_MAINTAIN,
                        "设备进水": self.FISHING_FINE_DEVICE,
                        "渔政罚款": self.FISHING_FINE_POLICE,
                        "撞上暗礁": self.FISHING_FINE_REEF,
                        "河豚毒素": 200, "鲨鱼来袭": 250, "鱼钩卷刃": 80,
                        "巨浪拍船": 50, "鱼群暴动": 120, "冰雹灾害": 180, "水蛇惊魂": 100,
                    }
                    fine_desc = {
                        "钓具保养": "钓具该保养了，花 30 积分换个新鱼线",
                        "设备进水": "设备进水损坏，花 40 积分维修",
                        "渔政罚款": "被渔政突击检查，无证捕捞罚款 100 积分！",
                        "撞上暗礁": "船撞上暗礁！维修费 150 积分…",
                        "河豚毒素": "处理河豚时中毒，医药费 200 积分！",
                        "鲨鱼来袭": "鲨鱼撞坏渔船，赔偿 250 积分！",
                        "鱼钩卷刃": "鱼钩卷刃无法使用，花 80 积分更换",
                        "巨浪拍船": "巨浪拍上船头，设备受损 50 积分",
                        "鱼群暴动": "鱼群暴动撞翻鱼篓，损失 120 积分",
                        "冰雹灾害": "遭遇冰雹，船顶被砸 180 积分",
                        "水蛇惊魂": "被水蛇吓到扭伤腰，医药费 100 积分",
                    }
                    amount = fine_map[event]
                    # 余额不足时只扣到 0，避免事务失败中断判定
                    fine = min(int(amount), int(await self._balance(session, uid)))
                    if fine > 0:
                        await self._add_points(session, uid, -fine, f"钓鱼罚款-{event}")
                        notify(f"{fine_desc[event]}（-{fine} 积分）")
                    else:
                        notify(f"{fine_desc[event]}（穷得叮当响，赊账了喵…）")
                elif event in ("鱼竿断裂", "海怪来袭", "雷电击中"):
                    await session.execute(
                        text("UPDATE fishing_rods SET status='broken' WHERE id=:i"), {"i": rid}
                    )
                    if event == "鱼竿断裂":
                        notify("啪！鱼竿断了，记得 /修鱼竿 哦~")
                    elif event == "海怪来袭":
                        notify("被海怪吓了一跳，鱼跑了，鱼竿也断了…")
                    else:
                        fine = min(300, int(await self._balance(session, uid)))
                        if fine > 0:
                            await self._add_points(session, uid, -fine, "钓鱼罚款-雷电击中")
                        notify(f"雷电击中船桅！设备烧毁损失 {fine} 积分，鱼竿也断了…")
                elif event in ("磁暴干扰", "灯塔故障"):
                    # 挂机中断：鱼竿回到 idle（无需修理）
                    await session.execute(
                        text("UPDATE fishing_rods SET status='idle' WHERE id=:i"), {"i": rid}
                    )
                    notify("磁暴干扰了设备，挂机中断休息…" if event == "磁暴干扰"
                           else "灯塔故障一片漆黑，提前收工…")
                elif event == "鱼篓破洞":
                    lost_n = random.randint(1, 3)
                    lost_rows = (await session.execute(text(
                        "SELECT id, fish_name, is_shiny FROM fishing_inventory WHERE user_id=:u "
                        "ORDER BY RANDOM() LIMIT :n"
                    ), {"u": uid, "n": lost_n})).all()
                    if lost_rows:
                        for r in lost_rows:
                            await session.execute(text(
                                "DELETE FROM fishing_inventory WHERE id=:i"
                            ), {"i": r[0]})
                        lost_names = "、".join(
                            (f"{self.FISHING_SHINY_PREFIX}{r[1]}" if int(r[2] or 0) else str(r[1]))
                            for r in lost_rows
                        )
                        notify(f"鱼篓破了个洞，{lost_names} 溜走了…")
                    else:
                        notify("鱼篓破了个洞，好在鱼篓是空的…")
                elif event == "海鸥偷食":
                    lost = min(2, bait - 1)
                    if lost > 0:
                        await session.execute(
                            text("UPDATE fishing_baits SET count=count-:c WHERE user_id=:u"),
                            {"c": lost, "u": uid},
                        )
                        notify(f"海鸥俯冲偷食，损失 {lost} 个鱼饵…")
                    else:
                        notify("海鸥俯冲偷食，好在没偷到鱼饵")
                elif event == "大鱼拔河":
                    notify("和大鱼拔河输了，眼睁睁看它跑掉…")
                elif event == "暴风雨":
                    notify("遇上暴风雨，空手而归…")
                # 空钩：普通事件也播报一下
                elif event == "空钩":
                    notify("守了半天，只有鱼饵被啃了，啥也没钓到…")
                    await self._fishing_task_streak(session, uid, broke=True)
                elif event in ("水草缠竿", "暗流漩涡", "锚被卡住"):
                    skip_desc = {
                        "水草缠竿": "水草缠住鱼竿，折腾半天才解开，本次判定跳过…",
                        "暗流漩涡": "遇上暗流漩涡，鱼漂打转，本次判定跳过…",
                        "锚被卡住": "锚被水底石头卡住，忙活半天啥也没捞到…",
                    }
                    notify(skip_desc[event])
                elif event in ("雾锁海面", "乌贼喷墨", "海市蜃楼", "钓到水草团"):
                    fog_desc = {
                        "雾锁海面": "大雾弥漫海面，啥也看不见，空手而归…",
                        "乌贼喷墨": "乌贼喷了一船墨，黑漆漆啥也没有…",
                        "海市蜃楼": "看到一条大鱼跃出水面，可惜只是海市蜃楼…",
                        "钓到水草团": "拉上来一大团水草，一无所得…",
                    }
                    notify(fog_desc[event])
                # 自动收鱼器生效中：本竿判定结束后把渔获（含本轮新钓的）直接收进鱼篓
                if self._shop_active(self._active_shop or {}, "auto"):
                    got = await self._fishing_auto_collect(session, uid)
                    if got:
                        notify(f"的自动收鱼器把 {got} 条鱼收进了鱼篓")
                # 系统钱包奖池抽成：上钩判定有概率从资金池抽比例积分奖励玩家
                if event in multi_map:
                    reward_info = await self.trigger_fishing_reward(session, uid, user_name)
                    if reward_info:
                        reward, percent = reward_info
                        notify(
                            f"🎉 触发系统奖池抽成！从资金池获得 {reward} 积分"
                            f"（钱包的 {percent:.2f}%）"
                        )
            return True, "判定完成", (broadcasts, notices)

        ok, msg, data = await self._tx(fn)
        if not ok or not data:
            self.logger.warning(f"钓鱼判定未执行：{msg}")
            return
        broadcasts, notices = data
        self.logger.info(f"钓鱼判定完成：播报 {len(notices)} 条事件，{len(broadcasts)} 条高价广播")
        # 事务外发送全群广播，避免阻塞数据库
        for platform_id, group_id, chain in broadcasts:
            await self._send_with_fallback(platform_id, group_id, chain, "钓鱼高价广播")
        # 事件播报：按群聚合所有人的播报，合并渲染成一张图发送
        # 渲染优先级：平台 t2i 服务（text_to_image，网络失败自动落 Playwright）
        #           → 本地 PIL 汇总海报（fishing_poster）→ 纯文字兜底
        # 只按群号聚合（同群跨平台实例的播报合并为一条消息，避免拆成多张图）
        per_group: dict[str, dict] = {}
        if self.FISHING_BROADCAST_GROUPS:
            # 配置了播报群：所有源群的事件合并成一张图统一推送。
            # 播报群本身就是"全服实况频道"，若按源群逐张推送，
            # 玩家跨多个群挂机时播报群一个周期会收到多张图。
            per_group["__broadcast__"] = {
                "platform": "", "lines": [str(t[2]) for t in notices]}
        else:
            # 未配置播报群：只按群号聚合（同群跨平台实例合并为一条消息），
            # 且只发目标群（cross_group_fallback=False，别群的图不漏进来）
            for platform_id, group_id, text_line in notices:
                g = str(group_id)
                if g not in per_group:
                    per_group[g] = {"platform": str(platform_id), "lines": []}
                per_group[g]["lines"].append(str(text_line))
        # 烛心站点：保存本次播报快照（覆盖旧的，只留最新）
        try:
            _zhuxin_save_broadcast("fish", per_group)
        except Exception:
            pass
        for group_id, info in per_group.items():
            platform_id = info["platform"]
            lines = info["lines"]
            aggregate = "\n".join(lines)
            img_chain = None
            # 首选：自定义「烛之播报」模板走 t2i 服务（成员分卡、每条动态一行）
            if FISHING_T2I_TEMPLATE:
                members_d: dict[str, list] = {}
                m_order: list[str] = []
                for line in lines:
                    parts = line.split(" ", 2)
                    who = parts[1] if len(parts) >= 2 and parts[0] == "🎣" else "未知"
                    ev = parts[2] if len(parts) >= 3 else line
                    if who not in members_d:
                        members_d[who] = []
                        m_order.append(who)
                    members_d[who].append(ev)
                tmpl_data = {
                    "date": datetime.now(TZ).strftime("%m月%d日 %H:%M"),
                    "members": [
                        {"name": w, "events": members_d[w]} for w in m_order
                    ],
                }
                try:
                    raw = await _t2i_render_direct(FISHING_T2I_TEMPLATE, tmpl_data)
                    img_chain = [Image.fromBase64(base64.b64encode(raw).decode())]
                    try:
                        _zhuxin_save_broadcast_img("fish", data=raw)
                    except Exception:
                        pass
                except Exception:
                    self.logger.exception("烛之播报直连 t2i 渲染失败，尝试平台 t2i 策略")
                    img_chain = None
                if img_chain is None:
                    try:
                        renderer = _get_t2i_net_renderer()
                        ret = await renderer.render_custom_template(
                            FISHING_T2I_TEMPLATE, tmpl_data, return_url=True,
                        )
                        if isinstance(ret, str) and ret.startswith("http"):
                            img_chain = [Image.fromURL(ret)]
                    except Exception:
                        self.logger.exception("烛之播报平台 t2i 策略也失败，改用本地 PIL 海报")
                        img_chain = None
            # 其次：本地 PIL 汇总海报（自带字体，不依赖服务器环境）
            if img_chain is None and _render_fishing_batch is not None:
                img_path = None
                try:
                    fd, img_path = tempfile.mkstemp(prefix="fishing_bcast_", suffix=".png")
                    os.close(fd)
                    _render_fishing_batch(lines, img_path)
                    img_chain = [Image.fromFileSystem(img_path)]
                    try:
                        _zhuxin_save_broadcast_img("fish", src_path=img_path)
                    except Exception:
                        pass
                except Exception:
                    self.logger.exception("钓鱼播报汇总图渲染失败，本次回退文字播报")
                    img_chain = None
                    if img_path and os.path.exists(img_path):
                        try:
                            os.remove(img_path)
                        except OSError:
                            pass
            if img_chain is not None:
                try:
                    await self._send_with_fallback(
                        platform_id, group_id, img_chain, "钓鱼播报汇总图",
                        cross_group_fallback=False,
                    )
                finally:
                    # 清理本地临时文件（仅本地渲染路径产生的 mkstemp 文件）
                    for c in img_chain:
                        try:
                            fp = str(getattr(c, "path", "") or "")
                            if fp.startswith(tempfile.gettempdir()) and "fishing_bcast_" in fp and os.path.exists(fp):
                                os.remove(fp)
                        except Exception:
                            pass
            else:
                await self._send_with_fallback(
                    platform_id, group_id, [Plain(aggregate)], "钓鱼播报",
                    cross_group_fallback=False,
                )

    async def _fishing_daily_reset(self):
        """定时任务：每天凌晨 0 点重置今日统计（today_count / today_date）"""
        async def fn(session):
            await session.execute(text(
                "UPDATE fishing_stats SET today_count=0, today_date=:d"
            ), {"d": date.today().isoformat()})
            return True, "今日钓鱼统计已重置", None

        await self._tx(fn)

    async def _fishing_grant_titles(
        self, session, user_id: str, collected: set[str]
    ) -> list[str]:
        """图鉴收集奖励判定（必须在事务内调用），返回奖励提示列表。

        称号规则：
        - 钓到烛心 → 烛心持有者；钓到闲鱼 → 闲鱼之王（纯称号，无积分）
        - 同时拥有烛心和闲鱼 → 额外 1000 积分 + 至高传说之主（只发一次）
        - 集齐全部 102 种 → 5000 积分 + 万物之主（只发一次）
        """
        rewards: list[str] = []
        if {"烛心", "闲鱼"} <= collected:
            already = (await session.execute(text(
                "SELECT 1 FROM point_transactions WHERE user_id=:u AND operation='钓鱼至高奖励'"
            ), {"u": user_id})).first()
            if not already:
                await self._add_points(
                    session, user_id, self.FISHING_BOTH_LEGEND_REWARD, "钓鱼至高奖励"
                )
                rewards.append(
                    f"🏆 同时拥有烛心和闲鱼：获得「至高传说之主」称号 "
                    f"+{self.FISHING_BOTH_LEGEND_REWARD} 积分！"
                )
        if len(collected) >= len(FISH_POOL):
            already = (await session.execute(text(
                "SELECT 1 FROM point_transactions WHERE user_id=:u AND operation='钓鱼集齐奖励'"
            ), {"u": user_id})).first()
            if not already:
                await self._add_points(
                    session, user_id, self.FISHING_FULL_REWARD, "钓鱼集齐奖励"
                )
                rewards.append(
                    f"👑 集齐全部 {len(FISH_POOL)} 种鱼：获得「万物之主」称号 "
                    f"+{self.FISHING_FULL_REWARD} 积分！"
                )
        return rewards

    @filter.command("买鱼竿")
    async def fishing_buy_rod(self, event: AstrMessageEvent):
        """/买鱼竿 —— 花费 200 积分购买一根鱼竿（最多 5 根）"""
        ok_gate, msg_gate = await self._check_group_gate(event, "买鱼竿")
        if not ok_gate:
            yield event.plain_result(msg_gate)
            return
        user_id = event.get_sender_id()

        async def fn(session):
            await self._ensure_user(session, user_id)
            remaining = await self._enforce_cooldown(session, user_id)
            if remaining > 0:
                raise _BizError(f"操作太频繁啦，请 {remaining} 秒后再试喵~")
            cnt = (await session.execute(text(
                "SELECT COUNT(*) FROM fishing_rods WHERE user_id=:u"
            ), {"u": user_id})).first()
            if int(cnt[0]) >= self.MAX_RODS:
                raise _BizError(f"鱼竿已经满 {self.MAX_RODS} 根啦，不能再买了喵~")
            slots = {int(r[0]) for r in (await session.execute(text(
                "SELECT slot FROM fishing_rods WHERE user_id=:u"
            ), {"u": user_id})).all()}
            slot = next(i for i in range(1, self.MAX_RODS + 1) if i not in slots)
            bal = await self._total_balance(session, user_id)
            if bal < self.ROD_COST:
                raise _BizError(
                    f"积分不足喵~ 买鱼竿需要 {self.ROD_COST} 积分，你只有 {bal} 积分"
                )
            await self._add_points(session, user_id, -self.ROD_COST, "buy_rod")
            await session.execute(text(
                "INSERT INTO fishing_rods(user_id, slot, status, created_at) "
                "VALUES(:u, :s, 'idle', :t)"
            ), {"u": user_id, "s": slot, "t": time.time()})
            new_bal = await self._balance(session, user_id)
            return True, (
                f"🎣 购买成功！获得 {slot} 号鱼竿，花费 {self.ROD_COST} 积分，"
                f"当前积分：{new_bal} 喵~"
            ), None

        ok, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    @filter.command("买鱼饵")
    async def fishing_buy_bait(self, event: AstrMessageEvent):
        """/买鱼饵 [数量] —— 10 积分/个购买鱼饵，不填数量默认买 1 个"""
        ok_gate, msg_gate = await self._check_group_gate(event, "买鱼饵")
        if not ok_gate:
            yield event.plain_result(msg_gate)
            return
        user_id = event.get_sender_id()
        count = 1
        args = self._strip_command(event, "买鱼饵")
        if args:
            try:
                count = int(args.split()[0])
                if count <= 0:
                    raise ValueError
            except ValueError:
                yield event.plain_result("鱼饵数量得是正整数喵~")
                return

        async def fn(session):
            await self._ensure_user(session, user_id)
            remaining = await self._enforce_cooldown(session, user_id)
            if remaining > 0:
                raise _BizError(f"操作太频繁啦，请 {remaining} 秒后再试喵~")
            cost = count * self.BAIT_COST
            bal = await self._total_balance(session, user_id)
            if bal < cost:
                raise _BizError(
                    f"积分不足喵~ 买 {count} 个鱼饵需要 {cost} 积分，你只有 {bal} 积分"
                )
            await self._add_points(session, user_id, -cost, "buy_bait")
            await session.execute(text(
                "INSERT INTO fishing_baits(user_id, count) VALUES(:u, :c) "
                "ON CONFLICT(user_id) DO UPDATE SET count=fishing_baits.count+:c"
            ), {"u": user_id, "c": count})
            bait = await self._fishing_bait_count(session, user_id)
            new_bal = await self._balance(session, user_id)
            return True, (
                f"🪱 购买成功！获得 {count} 个鱼饵（花费 {cost} 积分），"
                f"现有鱼饵 {bait} 个，当前积分：{new_bal} 喵~"
            ), None

        ok, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    @filter.command("挂机钓鱼")
    async def fishing_start(self, event: AstrMessageEvent):
        """/挂机钓鱼 [编号] —— 让鱼竿开始挂机，不填编号则全部待机鱼竿一起挂机"""
        ok_gate, msg_gate = await self._check_group_gate(event, "挂机钓鱼")
        if not ok_gate:
            yield event.plain_result(msg_gate)
            return
        user_id = event.get_sender_id()
        platform_id = str(event.get_platform_id() or "")
        group_id = str(event.get_group_id() or "")
        args = self._strip_command(event, "挂机钓鱼")

        async def fn(session):
            await self._fishing_ensure_stats(session, user_id)
            remaining = await self._enforce_cooldown(session, user_id)
            if remaining > 0:
                raise _BizError(f"操作太频繁啦，请 {remaining} 秒后再试喵~")
            rods = (await session.execute(text(
                "SELECT id, slot, status FROM fishing_rods WHERE user_id=:u ORDER BY slot"
            ), {"u": user_id})).all()
            if not rods:
                raise _BizError("你还没有鱼竿，先 /买鱼竿 喵~")
            # 选出目标鱼竿
            if args:
                try:
                    slot = int(args.split()[0])
                except ValueError:
                    raise _BizError("鱼竿编号得是数字喵~")
                matched = [r for r in rods if int(r[1]) == slot]
                if not matched:
                    raise _BizError(f"没有 {slot} 号鱼竿喵~ 发 /鱼竿列表 查看你的鱼竿")
                rod = matched[0]
                if rod[2] == "fishing":
                    raise _BizError(f"{slot} 号鱼竿已经在挂机啦喵~")
                if rod[2] == "broken":
                    raise _BizError(f"{slot} 号鱼竿断了，先 /修鱼竿 {slot} 喵~")
                targets = [rod]
            else:
                targets = [r for r in rods if r[2] == "idle"]
                if not targets:
                    raise _BizError("没有待机的鱼竿喵~（挂机中或损坏的竿不能用）")
            bait = await self._fishing_bait_count(session, user_id)
            if bait <= 0:
                raise _BizError("没有鱼饵啦，先 /买鱼饵 再来钓鱼喵~")
            weather_key, weather_cfg = await self._weather_today(session)
            # 鱼饵不足以全覆盖时只启动部分鱼竿（每次判定每竿消耗 1 个鱼饵）
            start_n = min(len(targets), bait)
            for rod in targets[:start_n]:
                await session.execute(text(
                    "UPDATE fishing_rods SET status='fishing', platform_id=:p, group_id=:g "
                    "WHERE id=:i"
                ), {"p": platform_id, "g": group_id, "i": rod[0]})
            msg = (
                f"🎣 今日天气{weather_cfg['name']}！{weather_cfg['desc']}！\n"
                f"{start_n} 根鱼竿开始挂机啦！每 {self.CHECK_INTERVAL} 分钟判定一次，"
                f"每次每竿消耗 1 个鱼饵，钓到的鱼用 /收鱼 收取喵~"
            )
            if start_n < len(targets):
                msg += f"\n（鱼饵只够 {start_n} 根竿，剩下的先补鱼饵喵~）"
            return True, msg, None

        ok, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    @filter.command("收鱼")
    async def fishing_collect(self, event: AstrMessageEvent):
        """/收鱼 —— 把 pending 里的鱼收进鱼篓，并记录图鉴/判定收集奖励"""
        ok_gate, msg_gate = await self._check_group_gate(event, "收鱼")
        if not ok_gate:
            yield event.plain_result(msg_gate)
            return
        user_id = event.get_sender_id()

        async def fn(session):
            await self._fishing_ensure_stats(session, user_id)
            remaining = await self._enforce_cooldown(session, user_id)
            if remaining > 0:
                raise _BizError(f"操作太频繁啦，请 {remaining} 秒后再试喵~")
            pending = (await session.execute(text(
                "SELECT fish_name, value_mult, COUNT(*) FROM fishing_pending WHERE user_id=:u "
                "GROUP BY fish_name, value_mult"
            ), {"u": user_id})).all()
            if not pending:
                raise _BizError("还没钓到鱼喵~ 挂机中的鱼竿每 30 分钟判定一次，等等再来")
            total = 0
            new_species: list[str] = []
            details: list[str] = []
            new_shiny = 0
            for name, mult, cnt in pending:
                name = str(name)
                cnt = int(cnt)
                mult = float(mult or 1)
                total += cnt
                base, is_shiny = self._shiny_split(name)
                price = int(self._shiny_price(base, is_shiny) * mult)
                rarity = FISH_POOL.get(base, (0, "未知", 0.0))[1]
                # 并入鱼篓（闪光版与普通版分行存放）
                await session.execute(text(
                    "INSERT INTO fishing_inventory(user_id, fish_name, is_shiny, value_mult, count) "
                    "VALUES(:u, :n, :s, :m, :c) "
                    "ON CONFLICT(user_id, fish_name, is_shiny) DO UPDATE SET "
                    "count=fishing_inventory.count+:c"
                ), {"u": user_id, "n": base, "s": is_shiny, "m": mult, "c": cnt})
                # 记录图鉴（钓到过即收集，卖鱼不影响进度；闪光版独立收录）
                result = await session.execute(text(
                    "INSERT OR IGNORE INTO fishing_collection(user_id, fish_name, first_time) "
                    "VALUES(:u, :n, :t)"
                ), {"u": user_id, "n": name, "t": time.time()})
                if result.rowcount == 1:
                    new_species.append(f"{name}（{rarity}·{price}积分）")
                    if is_shiny:
                        new_shiny += 1
                details.append(f"{name}×{cnt}")
            await session.execute(
                text("DELETE FROM fishing_pending WHERE user_id=:u"), {"u": user_id}
            )
            # 图鉴收集奖励判定（烛心/闲鱼/集齐）
            collected = {str(r[0]) for r in (await session.execute(text(
                "SELECT fish_name FROM fishing_collection WHERE user_id=:u"
            ), {"u": user_id})).all()}
            rewards = await self._fishing_grant_titles(session, user_id, collected)
            # 图鉴榜：按永久图鉴记录统计，卖鱼后也不会减少
            await session.execute(text(
                "UPDATE fishing_stats SET collection_count=:c WHERE user_id=:u"
            ), {"u": user_id, "c": len(collected)})
            # 闪光收集数同步 + 阶段奖励判定
            shiny_n, shiny_rewards = await self._fishing_shiny_sync(session, user_id)
            rewards.extend(shiny_rewards)
            msg = f"🐟 收鱼成功！本次进篓 {total} 条：{'、'.join(details)}喵~"
            if new_species:
                msg += f"\n✨ 图鉴新收录：{'、'.join(new_species)}"
            if new_shiny:
                msg += f"\n✨ 这是你的第 {shiny_n} 种闪光鱼！"
            for line in rewards:
                msg += f"\n{line}"
            return True, msg, None

        ok, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    @filter.command("卖鱼")
    async def fishing_sell(self, event: AstrMessageEvent):
        """/卖鱼 —— 一键卖出鱼篓里所有鱼，按鱼类售价换算积分"""
        ok_gate, msg_gate = await self._check_group_gate(event, "卖鱼")
        if not ok_gate:
            yield event.plain_result(msg_gate)
            return
        user_id = event.get_sender_id()

        async def fn(session):
            await self._fishing_ensure_stats(session, user_id)
            remaining = await self._enforce_cooldown(session, user_id)
            if remaining > 0:
                raise _BizError(f"操作太频繁啦，请 {remaining} 秒后再试喵~")
            rows = (await session.execute(text(
                "SELECT fish_name, is_shiny, value_mult, count FROM fishing_inventory WHERE user_id=:u"
            ), {"u": user_id})).all()
            if not rows:
                raise _BizError("鱼篓里没有鱼可以卖喵~ 先 /挂机钓鱼 再来")
            total = 0
            fish_cnt = 0
            details: list[str] = []
            for name, is_shiny, mult, cnt in rows:
                name = str(name)
                cnt = int(cnt or 0)
                is_shiny = int(is_shiny or 0)
                mult = float(mult or 1)
                # 闪光版 ×3，大型鱼/满月乘数随渔获保留
                price = int(self._shiny_price(name, is_shiny) * mult)
                total += price * cnt
                fish_cnt += cnt
                display = f"{self.FISHING_SHINY_PREFIX}{name}" if is_shiny else name
                if mult >= self.FISHING_BIGFISH_MULT:
                    display = f"🐋{display}"
                details.append(f"{display}×{cnt}")
            # 卖鱼收入进账并记录流水（operation='sell_fish'），商店时效加成在此兑现
            shop = await self._get_shop_items(session, user_id)
            vip_on = self._shop_active(shop, "vip")
            double_on = self._shop_active(shop, "double")
            if vip_on:
                total = int(total * 1.1)
            eff_total = total * 2 if double_on else total
            # 组队收益加成
            team_mult = await self._team_bonus_mult(session, user_id)
            if team_mult > 1.0:
                eff_total = int(eff_total * team_mult)
            # 修仙加成：境界（每大境界+5%）+ 宗门（每级+1.5%）
            x_realm_mult, x_sect_mult = await self._xiuxian_income_bonus(session, user_id)
            if x_realm_mult > 1.0:
                eff_total = int(eff_total * x_realm_mult)
            if x_sect_mult > 1.0:
                eff_total = int(eff_total * x_sect_mult)
            await self._add_points(session, user_id, eff_total, "sell_fish", earned=eff_total)
            await session.execute(text(
                "UPDATE fishing_stats SET total_income=total_income+:t, "
                "total_fish_count=total_fish_count+:c WHERE user_id=:u"
            ), {"u": user_id, "t": eff_total, "c": fish_cnt})
            # 兼容旧数据：从本次售出的鱼中维护最高价值鱼（rows 为 4 列，解包要按列数来）
            best_name, best_value = max(
                ((str(row[0]), int(FISH_POOL.get(str(row[0]), (0,))[0])) for row in rows),
                key=lambda item: item[1], default=(None, 0)
            )
            current_best = (await session.execute(text(
                "SELECT best_fish_value FROM fishing_stats WHERE user_id=:u"
            ), {"u": user_id})).first()
            if best_name and (not current_best or best_value > int(current_best[0] or 0)):
                await session.execute(text(
                    "UPDATE fishing_stats SET best_fish_name=:n, best_fish_value=:v WHERE user_id=:u"
                ), {"u": user_id, "n": best_name, "v": best_value})
            await session.execute(
                text("DELETE FROM fishing_inventory WHERE user_id=:u"), {"u": user_id}
            )
            new_bal = await self._balance(session, user_id)
            return True, (
                f"💰 卖鱼成功！共卖出 {fish_cnt} 条：{'、'.join(details)}\n"
                f"收入 {total} 积分，当前积分：{new_bal} 喵~"
            ), None

        ok, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    @filter.command("鱼图鉴")
    async def fishing_book(self, event: AstrMessageEvent):
        """/鱼图鉴 —— 查看已收集鱼类种类与总进度（共 102 种）"""
        ok_gate, msg_gate = await self._check_group_gate(event, "鱼图鉴")
        if not ok_gate:
            yield event.plain_result(msg_gate)
            return
        user_id = event.get_sender_id()

        async def fn(session):
            collected = {str(r[0]) for r in (await session.execute(text(
                "SELECT fish_name FROM fishing_collection WHERE user_id=:u"
            ), {"u": user_id})).all()}
            # 闪光版以「✨闪光」前缀独立收录，与普通版分开统计
            prefix = self.FISHING_SHINY_PREFIX
            normal = {n for n in collected if not n.startswith(prefix)}
            shiny = {n for n in collected if n.startswith(prefix)}
            lines = [
                "📊 【鱼类图鉴】",
                f"已收集：{len(normal)}/{len(FISH_POOL)}种（普通）",
                f"✨ 闪光收集：{len(shiny)}/{len(FISH_POOL)}种（闪光）",
            ]
            for rarity, (_total_prob, fishes) in FISH_TABLE.items():
                names = {n for n, _p in fishes}
                lines.append(f"{rarity}：{len(names & normal)}/{len(names)}")
            if shiny:
                lines.append("✨ 已收集的闪光鱼：")
                lines.extend(f"✨ {n[len(prefix):]} ✅" for n in sorted(shiny))
            next_tier = next(
                ((need, pts) for need, pts, _t in self.FISHING_SHINY_REWARDS if len(shiny) < need),
                None,
            )
            if next_tier:
                lines.append(
                    f"🎯 下一阶段奖励：收集 {next_tier[0]} 种闪光鱼 → +{next_tier[1]} 积分"
                )
            return True, "\n".join(lines), None

        ok, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    @filter.command("钓鱼天气")
    async def fishing_weather_cmd(self, event: AstrMessageEvent):
        """/钓鱼天气 —— 查看今日钓鱼天气、效果加成与刷新倒计时"""
        ok_gate, msg_gate = await self._check_group_gate(event, "钓鱼天气")
        if not ok_gate:
            yield event.plain_result(msg_gate)
            return

        async def fn(session):
            _wkey, wcfg = await self._weather_today(session)
            now = datetime.now(self._beijing_tz)
            tomorrow = (now + timedelta(days=1)).replace(
                hour=0, minute=0, second=0, microsecond=0
            )
            left = tomorrow - now
            hours = left.seconds // 3600
            minutes = (left.seconds % 3600) // 60
            msg = (
                "🌤️ 【今日钓鱼天气】\n"
                f"天气：{wcfg['name']}\n"
                f"效果：{wcfg['desc']}\n"
                f"建议：{wcfg['advice']}\n"
                f"距离下次刷新：{hours}小时{minutes}分钟"
            )
            return True, msg, None

        ok, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    @filter.command("鱼竿列表")
    async def fishing_rod_list(self, event: AstrMessageEvent):
        """/鱼竿列表 —— 查看每根鱼竿的状态和鱼饵余量"""
        ok_gate, msg_gate = await self._check_group_gate(event, "鱼竿列表")
        if not ok_gate:
            yield event.plain_result(msg_gate)
            return
        user_id = event.get_sender_id()
        status_text = {"idle": "待机", "fishing": "挂机中", "broken": "已损坏"}

        async def fn(session):
            rods = (await session.execute(text(
                "SELECT slot, status FROM fishing_rods WHERE user_id=:u ORDER BY slot"
            ), {"u": user_id})).all()
            if not rods:
                raise _BizError("你还没有鱼竿，先 /买鱼竿 喵~")
            bait = await self._fishing_bait_count(session, user_id)
